//! Byte formatting.

use crate::options::ByteFormat;

const METRIC_UNITS: [&str; 7] = ["B", "KB", "MB", "GB", "TB", "PB", "EB"];
const BINARY_UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];

impl ByteFormat {
    /// The width of the formatted byte count, without trailing space.
    pub fn width(self) -> usize {
        match self {
            ByteFormat::Metric => 10,
            ByteFormat::Binary => 11,
            ByteFormat::Bytes => 12,
            ByteFormat::MiB | ByteFormat::MB => 12,
            ByteFormat::GB | ByteFormat::GiB => 10,
        }
    }

    /// Format a byte count without any padding.
    pub fn format_raw(self, bytes: u128) -> String {
        match self {
            ByteFormat::Bytes => format!("{} b", bytes),
            ByteFormat::Binary => auto_unit(bytes, 1024, &BINARY_UNITS, 3),
            ByteFormat::Metric => auto_unit(bytes, 1000, &METRIC_UNITS, 2),
            ByteFormat::GB => fixed_unit(bytes, 1_000_000_000.0, "GB"),
            ByteFormat::GiB => fixed_unit(bytes, 1_073_741_824.0, "GiB"),
            ByteFormat::MB => fixed_unit(bytes, 1_000_000.0, "MB"),
            ByteFormat::MiB => fixed_unit(bytes, 1_048_576.0, "MiB"),
        }
    }

    /// Format a byte count right-aligned to this format's width.
    pub fn display(self, bytes: u128) -> String {
        format!("{:>w$}", self.format_raw(bytes), w = self.width())
    }
}

fn fixed_unit(bytes: u128, divisor: f64, unit: &str) -> String {
    format!("{:.2} {}", bytes as f64 / divisor, unit)
}

fn auto_unit(bytes: u128, base: u128, units: &[&str; 7], unit_width: usize) -> String {
    let mut idx = 0usize;
    let mut threshold: u128 = 1;
    while idx + 1 < units.len() {
        let next = threshold * base;
        if bytes > next {
            threshold = next;
            idx += 1;
        } else {
            break;
        }
    }
    if idx == 0 {
        format!("{} {:>w$}", bytes, units[0], w = unit_width)
    } else {
        format!(
            "{:.2} {:>w$}",
            bytes as f64 / threshold as f64,
            units[idx],
            w = unit_width
        )
    }
}
EOF"}

