//! A tiny file logger producing simplelog-like output.

use std::fs::File;
use std::io::Write;
use std::path::Path;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

static LOG: Mutex<Option<File>> = Mutex::new(None);
static NEXT_THREAD_ID: AtomicUsize = AtomicUsize::new(2);

thread_local! {
    static THREAD_ID: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// Marks the calling thread as the main thread.
pub fn mark_main_thread() {
    THREAD_ID.with(|t| t.set(1));
}

fn thread_id() -> usize {
    THREAD_ID.with(|t| {
        if t.get() == 0 {
            t.set(NEXT_THREAD_ID.fetch_add(1, Ordering::Relaxed));
        }
        t.get()
    })
}

pub fn init(path: &Path) -> std::io::Result<()> {
    let file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)?;
    *LOG.lock().unwrap() = Some(file);
    Ok(())
}

pub fn enabled() -> bool {
    LOG.lock().map(|l| l.is_some()).unwrap_or(false)
}

fn timestamp() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let day = secs % 86400;
    format!("{:02}:{:02}:{:02}", day / 3600, (day / 60) % 60, day % 60)
}

pub fn info(msg: &str) {
    if let Ok(mut guard) = LOG.lock() {
        if let Some(f) = guard.as_mut() {
            let _ = writeln!(f, "{} [INFO] {}", timestamp(), msg);
        }
    }
}

pub fn debug(target: &str, msg: &str) {
    let tid = thread_id();
    if let Ok(mut guard) = LOG.lock() {
        if let Some(f) = guard.as_mut() {
            let _ = writeln!(f, "{} [DEBUG] ({}) {}: {}", timestamp(), tid, target, msg);
        }
    }
}
EOF"}

