//! Common traversal utilities shared by the aggregate and interactive modes.

use std::collections::{BTreeSet, HashSet};
use std::fs::Metadata;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

#[derive(Clone, Debug)]
pub struct WalkOptions {
    pub threads: usize,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub cross_filesystems: bool,
    pub ignore_dirs: BTreeSet<PathBuf>,
}

impl WalkOptions {
    pub fn size_of(&self, m: &Metadata) -> u64 {
        if self.apparent_size {
            m.len()
        } else {
            m.blocks().saturating_mul(512)
        }
    }

    /// Returns true if the directory at the given canonical path should not be entered.
    pub fn is_ignored(&self, canonical: &Path) -> bool {
        if self.ignore_dirs.is_empty() {
            return false;
        }
        if self.ignore_dirs.contains(canonical) {
            crate::logging::debug("dua::common", &format!("Ignored {:?}", canonical));
            true
        } else {
            false
        }
    }

    pub fn thread_pool(&self) -> rayon::ThreadPool {
        let mut builder = rayon::ThreadPoolBuilder::new();
        if self.threads > 0 {
            builder = builder.num_threads(self.threads);
        }
        builder
            .stack_size(16 * 1024 * 1024)
            .build()
            .unwrap_or_else(|_| {
                rayon::ThreadPoolBuilder::new()
                    .num_threads(1)
                    .build()
                    .expect("thread pool")
            })
    }
}

/// Keeps track of seen inodes of hard-linked entries.
#[derive(Default)]
pub struct InodeFilter {
    seen: Mutex<HashSet<(u64, u64)>>,
}

impl InodeFilter {
    /// Returns true if the entry was not seen before (or isn't hard-linked).
    pub fn add(&self, m: &Metadata) -> bool {
        if m.nlink() <= 1 {
            return true;
        }
        self.seen.lock().unwrap().insert((m.dev(), m.ino()))
    }

    pub fn clear(&self) {
        self.seen.lock().unwrap().clear();
    }
}

/// Canonicalize the given ignore directories, keeping those which can't be canonicalized as is.
pub fn canonicalize_ignore_dirs(dirs: &[PathBuf]) -> BTreeSet<PathBuf> {
    dirs.iter()
        .map(|d| std::fs::canonicalize(d).unwrap_or_else(|_| d.clone()))
        .collect()
}

/// Determine the paths to process.
///
/// If no path is given, all entries of the current directory are used.
/// If a single directory is given, we change into it and use all its entries.
pub fn derive_input_paths(input: Vec<PathBuf>, cross_filesystems: bool) -> std::io::Result<Vec<PathBuf>> {
    if input.len() > 1 {
        return Ok(input);
    }
    if input.len() == 1 {
        if !input[0].is_dir() {
            return Ok(input);
        }
        std::env::set_current_dir(&input[0])?;
    }
    cwd_entries(cross_filesystems)
}

pub fn cwd_entries(cross_filesystems: bool) -> std::io::Result<Vec<PathBuf>> {
    let device_id = if cross_filesystems {
        None
    } else {
        Some(std::fs::metadata(".")?.dev())
    };
    let mut out = Vec::new();
    for entry in std::fs::read_dir(".")? {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let is_symlink = match entry.file_type() {
            Ok(ft) => ft.is_symlink(),
            Err(_) => continue,
        };
        if is_symlink {
            continue;
        }
        if let Some(dev) = device_id {
            match entry.metadata() {
                Ok(m) if m.dev() == dev => {}
                _ => continue,
            }
        }
        out.push(PathBuf::from(entry.file_name()));
    }
    out.sort();
    Ok(out)
}
EOF"}

