{"command":"cd /workspace && cat > src/aggregate.rs <<'EOF'
//! The `aggregate` subcommand: print the disk usage of the given paths.

use crate::options::ByteFormat;
use crate::walk::{InodeFilter, WalkOptions};
use rayon::prelude::*;
use std::io::Write;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

#[derive(Debug)]
pub struct Statistics {
    pub entries_traversed: u64,
    pub smallest_file_in_bytes: u64,
    pub largest_file_in_bytes: u64,
}

struct Stats {
    entries: AtomicU64,
    smallest: AtomicU64,
    largest: AtomicU64,
}

impl Stats {
    fn record(&self, size: u64) {
        self.entries.fetch_add(1, Ordering::Relaxed);
        self.smallest.fetch_min(size, Ordering::Relaxed);
        self.largest.fetch_max(size, Ordering::Relaxed);
    }
}

struct Ctx<'a> {
    opts: &'a WalkOptions,
    inodes: &'a InodeFilter,
    stats: &'a Stats,
    device: u64,
}

impl Ctx<'_> {
    fn counted_size(&self, m: &std::fs::Metadata) -> u64 {
        if (self.opts.count_hard_links || self.inodes.add(m))
            && (self.opts.cross_filesystems || m.dev() == self.device)
        {
            self.opts.size_of(m)
        } else {
            0
        }
    }

    /// Returns (bytes, errors) of all children of the given directory, recursively.
    fn walk_children(&self, dir: &Path, canonical: &Path) -> (u128, u64) {
        let rd = match std::fs::read_dir(dir) {
            Ok(rd) => rd,
            Err(_) => return (0, 0),
        };
        let mut bytes: u128 = 0;
        let mut errors: u64 = 0;
        let mut subdirs: Vec<(PathBuf, PathBuf)> = Vec::new();
        for entry in rd {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => {
                    errors += 1;
                    continue;
                }
            };
            let path = entry.path();
            match std::fs::symlink_metadata(&path) {
                Ok(m) => {
                    let size = self.counted_size(&m);
                    self.stats.record(size);
                    bytes += size as u128;
                    if m.is_dir() && (self.opts.cross_filesystems || m.dev() == self.device) {
                        let canon = canonical.join(entry.file_name());
                        if !self.opts.is_ignored(&canon) {
                            subdirs.push((path, canon));
                        }
                    }
                }
                Err(_) => {
                    self.stats.record(0);
                    errors += 1;
                }
            }
        }
        let (b, e) = subdirs
            .par_iter()
            .map(|(p, c)| self.walk_children(p, c))
            .reduce(|| (0, 0), |a, b| (a.0 + b.0, a.1 + b.1));
        (bytes + b, errors + e)
    }
}

/// Returns (bytes, errors) for the given root path.
fn walk_root(opts: &WalkOptions, inodes: &InodeFilter, stats: &Stats, root: &Path) -> (u128, u64) {
    let followed = match std::fs::metadata(root) {
        Ok(m) => m,
        Err(_) => return (0, 1),
    };
    let meta = match std::fs::symlink_metadata(root) {
        Ok(m) => m,
        Err(_) => return (0, 1),
    };
    let ctx = Ctx {
        opts,
        inodes,
        stats,
        device: followed.dev(),
    };
    let size = ctx.counted_size(&meta);
    stats.record(size);
    let mut bytes = size as u128;
    let mut errors = 0;
    if followed.is_dir() {
        let canonical = std::fs::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
        if !opts.is_ignored(&canonical) {
            let (b, e) = ctx.walk_children(root, &canonical);
            bytes += b;
            errors += e;
        }
    }
    (bytes, errors)
}

fn write_line(
    out: &mut impl Write,
    format: ByteFormat,
    bytes: u128,
    path: &str,
    colored_path: bool,
    errors: u64,
) -> std::io::Result<()> {
    write!(out, "\x1b[32m{}\x1b[39m ", format.display(bytes))?;
    if colored_path {
        write!(out, "\x1b[36m{}\x1b[39m", path)?;
    } else {
        write!(out, "{}", path)?;
    }
    if errors > 0 {
        write!(
            out,
            "  <{} IO Error{}>",
            errors,
            if errors > 1 { "s" } else { "" }
        )?;
    }
    writeln!(out)
}

/// Run the aggregation, returning the total number of errors and the statistics.
pub fn aggregate(
    out: &mut impl Write,
    opts: &WalkOptions,
    compute_total: bool,
    sort_by_size: bool,
    format: ByteFormat,
    paths: Vec<PathBuf>,
) -> std::io::Result<(u64, Statistics)> {
    let pool = opts.thread_pool();
    let inodes = InodeFilter::default();
    let stats = Stats {
        entries: AtomicU64::new(0),
        smallest: AtomicU64::new(u64::MAX),
        largest: AtomicU64::new(0),
    };
    let mut total: u128 = 0;
    let mut total_errors: u64 = 0;
    let mut results: Vec<(PathBuf, u128, u64)> = Vec::new();
    let num_roots = paths.len();
    for path in paths {
        let (bytes, errors) = pool.install(|| walk_root(opts, &inodes, &stats, &path));
        total += bytes;
        total_errors += errors;
        if sort_by_size {
            results.push((path, bytes, errors));
        } else {
            write_line(
                out,
                format,
                bytes,
                &path.display().to_string(),
                !path.is_file(),
                errors,
            )?;
        }
    }
    if sort_by_size {
        results.sort_by_key(|r| r.1);
        for (path, bytes, errors) in &results {
            write_line(
                out,
                format,
                *bytes,
                &path.display().to_string(),
                !path.is_file(),
