        Shell::PowerShell => {
            clap_complete::generate(clap_complete::Shell::PowerShell, &mut cmd, "dua", &mut out)
        }
        Shell::Zsh => clap_complete::generate(clap_complete::Shell::Zsh, &mut cmd, "dua", &mut out),
    }
}

fn run(args: Args) -> std::io::Result<i32> {
    if let Some(log_file) = &args.log_file {
        logging::init(log_file)?;
        logging::info(&format!("dua options={:#?}", args));
    }
    let ignore_dirs = walk::canonicalize_ignore_dirs(&args.ignore_dirs);
    logging::info(&format!("Ignoring canonicalized {:?}", ignore_dirs));
    let walk_options = walk::WalkOptions {
        threads: args.threads,
        apparent_size: args.apparent_size,
        count_hard_links: args.count_hard_links,
        cross_filesystems: !args.stay_on_filesystem,
        ignore_dirs,
    };
