#!/usr/bin/env python3
"""Parse tmux capture-pane -e output into a grid of cells with attributes."""
import sys, re, subprocess, json

def default_attr():
    return {'fg': None, 'bg': None, 'b': 0, 'd': 0, 'i': 0, 'u': 0, 'r': 0, 'k': 0, 's': 0}

