        elif p == 2: attr['d'] = 1
        elif p == 3: attr['i'] = 1
        elif p == 4: attr['u'] = 1
        elif p == 5: attr['k'] = 1
        elif p == 7: attr['r'] = 1
        elif p == 9: attr['s'] = 1
        elif p == 22: attr['b'] = 0; attr['d'] = 0
        elif p == 23: attr['i'] = 0
        elif p == 24: attr['u'] = 0
        elif p == 25: attr['k'] = 0
        elif p == 27: attr['r'] = 0
        elif p == 29: attr['s'] = 0
        elif 30 <= p <= 37: attr['fg'] = p - 30
        elif p == 39: attr['fg'] = None
        elif 40 <= p <= 47: attr['bg'] = p - 40
        elif p == 49: attr['bg'] = None
        elif 90 <= p <= 97: attr['fg'] = p - 90 + 8
        elif 100 <= p <= 107: attr['bg'] = p - 100 + 8
        elif p in (38, 48):
            key = 'fg' if p == 38 else 'bg'
            if ps[i+1] == 5:
                attr[key] = ps[i+2]; i += 2
            elif ps[i+1] == 2:
                attr[key] = 'rgb(%d,%d,%d)' % tuple(ps[i+2:i+5]); i += 4
        i += 1

def parse(text, width):
    rows = []
    attr = default_attr()
    for line in text.split('\n'):
        cells = []
        i = 0
        while i < len(line):
            c = line[i]
            if c == '\x1b':
                m = re.match(r'\x1b\[([0-9;:]*)m', line[i:])
                if m:
                    apply_sgr(attr, m.group(1))
                    i += len(m.group(0))
                    continue
                m = re.match(r'\x1b\][^\x07]*\x07', line[i:])
                if m:
                    i += len(m.group(0)); continue
                i += 1
                continue
            cells.append((c, dict(attr)))
            i += 1
        rows.append(cells)
    return rows

def attr_str(a):
    s = []
    if a['fg'] is not None: s.append('fg=%s' % a['fg'])
    if a['bg'] is not None: s.append('bg=%s' % a['bg'])
    for k in 'bdiukrs':
        if a[k]: s.append(k)
    return ','.join(s)

def capture(target):
    out = subprocess.run(['tmux', 'capture-pane', '-t', target, '-p', '-e', '-N'], capture_output=True, text=True).stdout
    return out

def render(rows):
    """Text plus run-length encoded attributes per line."""
    res = []
    for y, cells in enumerate(rows):
        text = ''.join(c for c, _ in cells)
        runs = []
        prev = None
        start = 0
        for x, (c, a) in enumerate(cells):
            s = attr_str(a)
            if s != prev:
                if prev is not None and prev != '':
                    runs.append('%d-%d:%s' % (start, x - 1, prev))
                prev = s
                start = x
        if prev:
            runs.append('%d-%d:%s' % (start, len(cells) - 1, prev))
        res.append((text, runs))
    return res

if __name__ == '__main__':
    target = sys.argv[1]
    mode = sys.argv[2] if len(sys.argv) > 2 else 'full'
    rows = parse(capture(target), 0)
    for y, (text, runs) in enumerate(render(rows)):
        if mode == 'text':
            print(text.rstrip())
        else:
            print('%2d|%s' % (y, text.rstrip()))
            if runs:
                print('  @ ' + ' '.join(runs))
