    pub fn path_of(&self, id: NodeId) -> PathBuf {
        let mut parts: Vec<&Path> = Vec::new();
        let mut cur = id;
        while let Some(p) = self.nodes[cur].parent {
            parts.push(&self.nodes[cur].name);
            cur = p;
        }
        let mut path = PathBuf::new();
        for part in parts.into_iter().rev() {
            path.push(part);
        }
        path
    }

    /// Path relative to `ancestor`, which must be an ancestor of `id`.
    pub fn path_relative_to(&self, id: NodeId, ancestor: NodeId) -> PathBuf {
        let mut parts: Vec<&Path> = Vec::new();
        let mut cur = id;
        while cur != ancestor {
            parts.push(&self.nodes[cur].name);
            match self.nodes[cur].parent {
                Some(p) => cur = p,
                None => break,
            }
        }
        let mut path = PathBuf::new();
        for part in parts.into_iter().rev() {
            path.push(part);
        }
        path
    }

    pub fn is_ancestor_or_self(&self, ancestor: NodeId, id: NodeId) -> bool {
        let mut cur = Some(id);
        while let Some(c) = cur {
            if c == ancestor {
                return true;
            }
            cur = self.nodes[c].parent;
        }
        false
    }

