    pub fn attach(&mut self, parent: NodeId, tmp: TmpNode) -> NodeId {
        let id = self.nodes.len();
        self.nodes.push(Node {
            name: tmp.name,
            size: tmp.size,
            mtime: tmp.mtime,
            entry_count: tmp.entry_count,
            is_dir: tmp.is_dir,
            metadata_io_error: tmp.metadata_io_error,
            parent: Some(parent),
            children: Vec::with_capacity(tmp.children.len()),
            alive: true,
        });
        self.nodes[parent].children.push(id);
        for child in tmp.children {
            self.attach(id, child);
        }
        id
    }

