                let _ = own;
            }
            cur = self.nodes[p].parent;
        }
    }

    pub fn is_alive(&self, id: NodeId) -> bool {
        id < self.nodes.len() && self.nodes[id].alive
    }
}

/// A node as produced by the walker, before insertion into the tree.
#[derive(Debug)]
pub struct TmpNode {
    pub name: PathBuf,
    pub size: u128,
    pub mtime: SystemTime,
    pub entry_count: Option<u64>,
    pub is_dir: bool,
    pub metadata_io_error: bool,
    pub children: Vec<TmpNode>,
}

pub struct Progress {
    pub entries: AtomicU64,
    pub cancelled: AtomicBool,
}

impl Default for Progress {
    fn default() -> Self {
        Progress {
            entries: AtomicU64::new(0),
            cancelled: AtomicBool::new(false),
        }
    }
}

pub struct Walker<'a> {
    pub opts: &'a WalkOptions,
    pub inodes: &'a InodeFilter,
    pub progress: &'a Progress,
}

fn mtime_of(m: &std::fs::Metadata) -> SystemTime {
    m.modified().unwrap_or(UNIX_EPOCH)
}

impl Walker<'_> {
    fn counted_size(&self, m: &std::fs::Metadata, device: u64) -> u128 {
        if (self.opts.count_hard_links || self.inodes.add(m))
            && (self.opts.cross_filesystems || m.dev() == device)
        {
            self.opts.size_of(m) as u128
        } else {
            0
        }
    }

    /// Traverse a root path. Returns None if the root can't be accessed.
    pub fn walk_root(&self, path: &Path) -> Option<TmpNode> {
        let followed = std::fs::metadata(path).ok()?;
        let meta = std::fs::symlink_metadata(path).ok()?;
        self.progress.entries.fetch_add(1, Ordering::Relaxed);
        let device = followed.dev();
        let size = self.counted_size(&meta, device);
        let mut node = TmpNode {
            name: path.to_path_buf(),
            size,
            mtime: mtime_of(&meta),
            entry_count: None,
            is_dir: followed.is_dir(),
            metadata_io_error: false,
            children: Vec::new(),
