            let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
            if !self.opts.is_ignored(&canonical) {
                self.fill_children(&mut node, path, &canonical, device);
            }
        }
        Some(node)
    }

    fn fill_children(&self, node: &mut TmpNode, dir: &Path, canonical: &Path, device: u64) {
        if self.progress.cancelled.load(Ordering::Relaxed) {
            return;
        }
        let rd = match std::fs::read_dir(dir) {
            Ok(rd) => rd,
            Err(_) => return,
        };
        let mut children: Vec<(TmpNode, Option<(PathBuf, PathBuf)>)> = Vec::new();
        for entry in rd {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            self.progress.entries.fetch_add(1, Ordering::Relaxed);
            let name = PathBuf::from(entry.file_name());
            let path = entry.path();
            match std::fs::symlink_metadata(&path) {
