                    let is_dir = m.is_dir();
                    let mut descend = None;
                    if is_dir && (self.opts.cross_filesystems || m.dev() == device) {
                        let canon = canonical.join(entry.file_name());
                        if !self.opts.is_ignored(&canon) {
                            descend = Some((path, canon));
                        }
                    }
                    children.push((
                        TmpNode {
                            name,
                            size,
                            mtime: mtime_of(&m),
                            entry_count: None,
                            is_dir,
                            metadata_io_error: false,
                            children: Vec::new(),
                        },
                        descend,
                    ));
                }
                Err(_) => {
                    children.push((
                        TmpNode {
                            name,
                            size: 0,
                            mtime: UNIX_EPOCH,
                            entry_count: None,
                            is_dir: false,
                            metadata_io_error: true,
                            children: Vec::new(),
                        },
                        None,
                    ));
                }
            }
        }
        children.par_iter_mut().for_each(|(child, descend)| {
            if let Some((path, canon)) = descend.take() {
                self.fill_children(child, &path, &canon, device);
            }
        });
        let had_children = !children.is_empty();
        let mut count: u64 = 1;
        for (child, _) in children {
            node.size += child.size;
            if !child.metadata_io_error {
                count += child.entry_count.unwrap_or(1);
            }
            node.children.push(child);
        }
        if had_children {
            node.entry_count = Some(count);
        }
    }
}

pub fn os_name(p: &Path) -> OsString {
    p.as_os_str().to_os_string()
}
