    NameAscending,
    NameDescending,
}

impl SortMode {
    pub fn describe(self) -> &'static str {
        match self {
            SortMode::SizeDescending => "size descending",
            SortMode::SizeAscending => "size ascending",
            SortMode::MTimeDescending => "modified descending",
            SortMode::MTimeAscending => "modified ascending",
            SortMode::CountDescending => "items descending",
            SortMode::CountAscending => "items ascending",
            SortMode::NameAscending => "name ascending",
            SortMode::NameDescending => "name descending",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BarMode {
    PercentageAndBar,
    Percentage,
    Bar,
    LongBar,
}

impl BarMode {
    fn next(self) -> BarMode {
        match self {
            BarMode::PercentageAndBar => BarMode::Percentage,
            BarMode::Percentage => BarMode::Bar,
            BarMode::Bar => BarMode::LongBar,
            BarMode::LongBar => BarMode::PercentageAndBar,
        }
    }
}

#[derive(Clone, Debug)]
pub struct MarkedEntry {
    pub id: NodeId,
    pub path: PathBuf,
    pub size: u128,
    pub is_dir: bool,
    pub count: u64,
}

#[derive(Clone, Debug, Default)]
pub struct MarkPane {
    pub entries: Vec<MarkedEntry>,
    pub selected: usize,
    pub offset: usize,
}

impl MarkPane {
    pub fn total_count(&self) -> u64 {
        self.entries.iter().map(|e| e.count).sum()
    }
    pub fn total_size(&self) -> u128 {
        self.entries.iter().map(|e| e.size).sum()
    }
}

#[derive(Clone, Debug, Default)]
pub struct GlobInput {
    pub text: Vec<char>,
    pub cursor: usize,
}

#[derive(Clone, Debug)]
pub struct GlobView {
    /// The directory the search started from.
    pub root: NodeId,
    pub results: Vec<NodeId>,
}

pub enum Message {
    Info(String),
    QuitConfirm,
}

pub struct App {
    pub tree: Tree,
    pub root_title: String,
    pub format: ByteFormat,
    pub walk_options: WalkOptions,
    pub no_entry_check: bool,

    pub view_root: NodeId,
    pub glob_view: Option<GlobView>,
    /// Whether the glob view is the active view (as opposed to having navigated into a directory from it).
    pub in_glob_view: bool,
    pub selected: Option<NodeId>,
    pub bookmarks: HashMap<NodeId, NodeId>,
    pub list_offset: usize,

    pub sort: SortMode,
    pub show_mtime: bool,
    pub show_count: bool,
    pub bar_mode: BarMode,

    pub focus: Focus,
    pub help_open: bool,
    pub help_scroll: usize,
    pub mark: Option<MarkPane>,
    pub glob_input: Option<GlobInput>,
    pub glob_case_insensitive: bool,

    pub message: Option<Message>,
    pub missing: HashSet<NodeId>,

    pub scanning: bool,
    pub entries_processed: u64,
    pub elapsed: Duration,
    pub scan_start: Instant,

    pub should_quit: bool,
}

pub const HELP_LINE_COUNT: usize = 64;

impl App {
    pub fn new(root_title: String, format: ByteFormat, walk_options: WalkOptions, no_entry_check: bool) -> App {
        App {
            tree: Tree::new_with_root(PathBuf::from(&root_title)),
            root_title,
            format,
            walk_options,
            no_entry_check,
            view_root: ROOT,
            glob_view: None,
            in_glob_view: false,
            selected: None,
            bookmarks: HashMap::new(),
            list_offset: 0,
            sort: SortMode::SizeDescending,
            show_mtime: false,
            show_count: false,
            bar_mode: BarMode::PercentageAndBar,
            focus: Focus::Main,
            help_open: false,
            help_scroll: 0,
            mark: None,
            glob_input: None,
            glob_case_insensitive: true,
            message: None,
            missing: HashSet::new(),
            scanning: true,
            entries_processed: 0,
            elapsed: Duration::ZERO,
            scan_start: Instant::now(),
            should_quit: false,
        }
    }

    pub fn mtime_column_visible(&self) -> bool {
        self.show_mtime || matches!(self.sort, SortMode::MTimeAscending | SortMode::MTimeDescending)
    }

    pub fn count_column_visible(&self) -> bool {
        self.show_count || matches!(self.sort, SortMode::CountAscending | SortMode::CountDescending)
    }

    pub fn glob_pane_open(&self) -> bool {
        self.glob_input.is_some()
    }

    /// The name used for display and sorting of an entry in the current view.
    pub fn display_name(&self, id: NodeId) -> PathBuf {
        if self.in_glob_view {
            self.tree.path_of(id)
        } else {
            self.tree.nodes[id].name.clone()
        }
    }

    /// The entries of the current view, sorted.
    pub fn entries(&self) -> Vec<NodeId> {
        let tree = &self.tree;
        let mut v: Vec<NodeId> = if self.in_glob_view {
            self.glob_view
                .as_ref()
                .map(|g| g.results.iter().copied().filter(|id| tree.is_alive(*id)).collect())
                .unwrap_or_default()
        } else {
            let mut v: Vec<NodeId> = tree.children(self.view_root).collect();
            v.sort_by(|a, b| tree.nodes[*b].name.cmp(&tree.nodes[*a].name));
            v
        };
        let names: HashMap<NodeId, PathBuf> = if self.in_glob_view {
            v.iter().map(|id| (*id, tree.path_of(*id))).collect()
        } else {
            HashMap::new()
        };
        let name = |id: &NodeId| -> &std::path::Path {
            match names.get(id) {
                Some(p) => p.as_path(),
                None => tree.nodes[*id].name.as_path(),
            }
        };
        let node = |id: &NodeId| &tree.nodes[*id];
        let cmp_count = |a: &NodeId, b: &NodeId| {
            node(a)
                .entry_count
                .cmp(&node(b).entry_count)
                .then_with(|| name(a).cmp(name(b)))
        };
        let cmp_name = |a: &NodeId, b: &NodeId| {
            node(b)
                .is_dir
                .cmp(&node(a).is_dir)
                .then_with(|| name(a).cmp(name(b)))
        };
        match self.sort {
            SortMode::SizeDescending => v.sort_by(|a, b| node(b).size.cmp(&node(a).size)),
            SortMode::SizeAscending => v.sort_by(|a, b| node(a).size.cmp(&node(b).size)),
            SortMode::MTimeDescending => v.sort_by(|a, b| node(b).mtime.cmp(&node(a).mtime)),
            SortMode::MTimeAscending => v.sort_by(|a, b| node(a).mtime.cmp(&node(b).mtime)),
            SortMode::CountAscending => v.sort_by(cmp_count),
            SortMode::CountDescending => v.sort_by(|a, b| cmp_count(a, b).reverse()),
            SortMode::NameAscending => v.sort_by(cmp_name),
            SortMode::NameDescending => v.sort_by(|a, b| cmp_name(a, b).reverse()),
        }
        v
    }

    pub fn selected_index(&self, entries: &[NodeId]) -> Option<usize> {
        let sel = self.selected?;
        entries.iter().position(|e| *e == sel)
    }

    pub fn is_marked(&self, id: NodeId) -> bool {
        self.mark
            .as_ref()
            .map(|m| m.entries.iter().any(|e| e.id == id))
            .unwrap_or(false)
    }

    fn set_info(&mut self, msg: &str) {
        self.message = Some(Message::Info(msg.to_string()));
    }

    // ---------------------------------------------------------------- scanning

    pub fn attach_root_child(&mut self, tmp: super::tree::TmpNode) {
        let size = tmp.size;
        let id = self.tree.attach(ROOT, tmp);
        let _ = id;
        self.tree.nodes[ROOT].size += size;
        if self.selected.is_none() && self.view_root == ROOT && !self.in_glob_view {
            // selection is established once scanning is done
        }
    }

    pub fn scan_finished(&mut self) {
        self.scanning = false;
        self.elapsed = self.scan_start.elapsed();
        if self.selected.is_none() {
            let entries = self.entries();
            self.selected = entries.first().copied();
        }
    }

    // ---------------------------------------------------------------- key handling

    pub fn handle_key(&mut self, key: KeyEvent) {
        if key.kind == KeyEventKind::Release {
            return;
        }
        let quit_confirm_pending = matches!(self.message, Some(Message::QuitConfirm));
        self.message = None;

        if key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL) {
            self.should_quit = true;
            return;
        }

        if self.focus == Focus::Glob {
            self.handle_glob_key(key);
            return;
        }

        match key.code {
            KeyCode::Tab => {
                self.cycle_focus();
                return;
            }
            KeyCode::Char('?') if key.modifiers.difference(KeyModifiers::SHIFT).is_empty() => {
                if self.focus == Focus::Help {
                    self.help_open = false;
                    self.focus = Focus::Main;
                } else {
                    self.help_open = true;
                    self.focus = Focus::Help;
                }
                return;
            }
            KeyCode::Char('/') if key.modifiers.is_empty() => {
                if self.focus != Focus::Help {
                    self.glob_input = Some(GlobInput::default());
                    self.focus = Focus::Glob;
                    return;
                }
            }
            KeyCode::Char('q') | KeyCode::Esc
                if key.modifiers.is_empty() || key.code == KeyCode::Esc =>
            {
                match self.focus {
                    Focus::Main => {
                        if self.in_glob_view || self.glob_view.is_some() {
                            self.exit_glob();
                        } else if self.mark.is_some() && !quit_confirm_pending {
                            self.message = Some(Message::QuitConfirm);
                        } else {
                            self.should_quit = true;
                        }
                    }
                    Focus::Help => {
                        self.help_open = false;
                        self.focus = Focus::Main;
                    }
                    Focus::Mark => {
                        self.focus = Focus::Main;
                    }
                    Focus::Glob => {}
                }
                return;
            }
            _ => {}
        }

        match self.focus {
            Focus::Main => self.handle_main_key(key),
            Focus::Help => self.handle_help_key(key),
            Focus::Mark => self.handle_mark_key(key),
            Focus::Glob => {}
        }
    }

    fn cycle_focus(&mut self) {
        let order = [Focus::Main, Focus::Help, Focus::Mark, Focus::Glob];
        let open = |f: Focus| match f {
            Focus::Main => true,
            Focus::Help => self.help_open,
            Focus::Mark => self.mark.is_some(),
            Focus::Glob => self.glob_pane_open(),
        };
        let idx = order.iter().position(|f| *f == self.focus).unwrap_or(0);
        for step in 1..=order.len() {
            let candidate = order[(idx + step) % order.len()];
            if open(candidate) {
                self.focus = candidate;
                return;
            }
        }
    }

    fn exit_glob(&mut self) {
        if let Some(g) = self.glob_view.take() {
            if self.in_glob_view {
                self.view_root = g.root;
            }
        }
        self.in_glob_view = false;
        self.glob_input = None;
        if self.focus == Focus::Glob {
            self.focus = Focus::Main;
        }
        let entries = self.entries();
        if self.selected_index(&entries).is_none() {
            self.selected = self
                .bookmarks
                .get(&self.view_root)
                .copied()
                .filter(|s| entries.contains(s))
                .or_else(|| entries.first().copied());
        }
        self.check_entries();
    }

    fn handle_glob_key(&mut self, key: KeyEvent) {
        let input = match self.glob_input.as_mut() {
            Some(i) => i,
            None => {
                self.focus = Focus::Main;
                return;
            }
        };
        match key.code {
            KeyCode::Esc => {
                self.exit_glob();
            }
            KeyCode::Tab => self.cycle_focus(),
            KeyCode::Enter => {
                let text: String = input.text.iter().collect();
                self.search(&text);
            }
            KeyCode::Backspace => {
                if input.cursor > 0 {
                    input.cursor -= 1;
                    input.text.remove(input.cursor);
                }
            }
            KeyCode::Left => {
                input.cursor = input.cursor.saturating_sub(1);
            }
            KeyCode::Right => {
                if input.cursor < input.text.len() {
                    input.cursor += 1;
                }
            }
            KeyCode::Char('f') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.glob_case_insensitive = !self.glob_case_insensitive;
            }
            KeyCode::Char(c) => {
                input.text.insert(input.cursor, c);
                input.cursor += 1;
            }
            _ => {}
        }
    }

    fn search(&mut self, text: &str) {
        if text.trim().is_empty() {
            self.set_info("Glob was empty or only whitespace");
            return;
        }
        let start = Instant::now();
        let search_root = if self.in_glob_view {
            self.glob_view.as_ref().map(|g| g.root).unwrap_or(self.view_root)
        } else {
            self.view_root
        };
        let pattern = Pattern::new(text);
        let mut results = Vec::new();
        let mut stack: Vec<NodeId> = Vec::new();
        // depth first, in tree order
        let children: Vec<NodeId> = self.tree.children(search_root).collect();
        for c in children.into_iter().rev() {
            stack.push(c);
        }
        while let Some(id) = stack.pop() {
            let node = &self.tree.nodes[id];
            let base = node.name.to_string_lossy().into_owned();
            let rel = self.tree.path_relative_to(id, search_root).to_string_lossy().into_owned();
            if pattern.matches(&base, &rel, self.glob_case_insensitive) {
                results.push(id);
                continue;
            }
            let children: Vec<NodeId> = self.tree.children(id).collect();
            for c in children.into_iter().rev() {
                stack.push(c);
            }
        }
        if results.is_empty() {
            self.set_info("No match found");
            return;
        }
        if !self.in_glob_view {
            if let Some(sel) = self.selected {
                self.bookmarks.insert(self.view_root, sel);
            }
        }
        self.glob_view = Some(GlobView {
            root: search_root,
            results,
        });
        self.in_glob_view = true;
        self.view_root = search_root;
        self.focus = Focus::Main;
        let entries = self.entries();
        self.selected = entries.first().copied();
        self.elapsed = start.elapsed();
    }

    fn move_selection(&mut self, entries: &[NodeId], f: impl Fn(usize, usize) -> usize) {
        if entries.is_empty() {
            return;
        }
        let cur = self.selected_index(entries).unwrap_or(0);
        let next = f(cur, entries.len()).min(entries.len() - 1);
        self.selected = Some(entries[next]);
    }

    fn handle_main_key(&mut self, key: KeyEvent) {
        let entries = self.entries();
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('j') | KeyCode::Down if !ctrl => {
                self.move_selection(&entries, |c, _| c + 1)
            }
            KeyCode::Char('k') | KeyCode::Up if !ctrl => {
                self.move_selection(&entries, |c, _| c.saturating_sub(1))
            }
            KeyCode::Char('d') if ctrl => self.move_selection(&entries, |c, _| c + 10),
            KeyCode::PageDown => self.move_selection(&entries, |c, _| c + 10),
            KeyCode::Char('u') if ctrl => {
                self.move_selection(&entries, |c, _| c.saturating_sub(10))
            }
            KeyCode::PageUp => self.move_selection(&entries, |c, _| c.saturating_sub(10)),
            KeyCode::Char('H') | KeyCode::Home => self.move_selection(&entries, |_, _| 0),
            KeyCode::Char('G') | KeyCode::End => self.move_selection(&entries, |_, l| l - 1),
            KeyCode::Char('o') | KeyCode::Char('l') | KeyCode::Enter | KeyCode::Right if !ctrl => {
                self.enter_selected()
            }
            KeyCode::Char('u') | KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace
                if !ctrl =>
            {
                self.exit_node()
            }
            KeyCode::Char('s') => {
                self.sort = if self.sort == SortMode::SizeDescending {
                    SortMode::SizeAscending
                } else {
                    SortMode::SizeDescending
                }
            }
            KeyCode::Char('m') => {
                self.sort = if self.sort == SortMode::MTimeDescending {
                    SortMode::MTimeAscending
                } else {
                    SortMode::MTimeDescending
                }
            }
            KeyCode::Char('c') => {
                self.sort = if self.sort == SortMode::CountDescending {
                    SortMode::CountAscending
                } else {
                    SortMode::CountDescending
                }
            }
            KeyCode::Char('n') => {
                self.sort = if self.sort == SortMode::NameAscending {
                    SortMode::NameDescending
                } else {
                    SortMode::NameAscending
                }
            }
            KeyCode::Char('M') => self.show_mtime = !self.show_mtime,
            KeyCode::Char('C') => self.show_count = !self.show_count,
            KeyCode::Char('g') | KeyCode::Char('S') => self.bar_mode = self.bar_mode.next(),
            KeyCode::Char('O') => self.open_selected(),
            KeyCode::Char('d') => {
                if let Some(sel) = self.selected {
                    self.toggle_mark(sel);
                    self.move_selection(&entries, |c, _| c + 1);
                }
            }
            KeyCode::Char('x') => {
                if let Some(sel) = self.selected {
                    if !self.is_marked(sel) {
                        self.toggle_mark(sel);
                    }
                    self.move_selection(&entries, |c, _| c + 1);
                }
            }
            KeyCode::Char(' ') => {
                if let Some(sel) = self.selected {
                    self.toggle_mark(sel);
                }
            }
            KeyCode::Char('a') => {
                for e in entries.iter() {
                    self.toggle_mark(*e);
                }
            }
            KeyCode::Char('r') => self.refresh_selected(),
            KeyCode::Char('R') => self.refresh_all(),
            _ => {}
        }
    }

    fn enter_selected(&mut self) {
        let sel = match self.selected {
            Some(s) => s,
            None => return,
        };
        if !self.tree.has_children(sel) {
            self.set_info("Entry is a file or an empty directory");
            return;
        }
        if let Some(cur) = self.selected {
            if !self.in_glob_view {
                self.bookmarks.insert(self.view_root, cur);
            }
        }
        self.in_glob_view = false;
        self.view_root = sel;
        let entries = self.entries();
        self.selected = self
            .bookmarks
            .get(&sel)
            .copied()
            .filter(|s| entries.contains(s))
            .or_else(|| entries.first().copied());
        self.check_entries();
    }

    fn exit_node(&mut self) {
        if self.in_glob_view {
            self.set_info("Top level reached");
            return;
        }
        if let Some(g) = self.glob_view.as_ref() {
            if self.tree.parent(self.view_root) == Some(g.root) || self.view_root == g.root {
                if let Some(sel) = self.selected {
                    self.bookmarks.insert(self.view_root, sel);
                }
                let came_from = self.view_root;
                self.in_glob_view = true;
                self.view_root = g.root;
                let entries = self.entries();
                self.selected = if entries.contains(&came_from) {
                    Some(came_from)
                } else {
                    entries.first().copied()
                };
                return;
            }
        }
        let parent = match self.tree.parent(self.view_root) {
            Some(p) => p,
            None => {
                self.set_info("Top level reached");
                return;
            }
        };
        if let Some(sel) = self.selected {
            self.bookmarks.insert(self.view_root, sel);
        }
        let came_from = self.view_root;
        self.view_root = parent;
        self.selected = Some(came_from);
        self.check_entries();
    }

    fn check_entries(&mut self) {
        if self.no_entry_check || self.in_glob_view {
            return;
        }
        let children: Vec<NodeId> = self.tree.children(self.view_root).collect();
        for c in children {
            let path = self.tree.path_of(c);
            if std::fs::symlink_metadata(&path).is_err() {
                self.missing.insert(c);
            } else {
                self.missing.remove(&c);
            }
        }
    }

    fn open_selected(&mut self) {
        if let Some(sel) = self.selected {
            let path = self.tree.path_of(sel);
            let _ = std::process::Command::new("xdg-open")
                .arg(&path)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .spawn();
        }
    }

    pub fn toggle_mark(&mut self, id: NodeId) {
        let mark = self.mark.get_or_insert_with(MarkPane::default);
        if let Some(pos) = mark.entries.iter().position(|e| e.id == id) {
            mark.entries.remove(pos);
            if mark.selected >= mark.entries.len() && mark.selected > 0 {
                mark.selected = mark.entries.len().saturating_sub(1);
            }
        } else {
            let node = &self.tree.nodes[id];
            mark.entries.push(MarkedEntry {
                id,
                path: self.tree.path_of(id),
                size: node.size,
                is_dir: node.is_dir,
                count: node.entry_count.unwrap_or(1),
            });
            mark.selected = mark.entries.len() - 1;
        }
        if mark.entries.is_empty() {
            self.mark = None;
            if self.focus == Focus::Mark {
                self.focus = Focus::Main;
            }
        }
    }

    fn handle_help_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('j') | KeyCode::Down if !ctrl => self.help_scroll += 1,
            KeyCode::Char('k') | KeyCode::Up if !ctrl => {
                self.help_scroll = self.help_scroll.saturating_sub(1)
            }
            KeyCode::Char('d') if ctrl => self.help_scroll += 10,
            KeyCode::PageDown => self.help_scroll += 10,
            KeyCode::Char('u') if ctrl => self.help_scroll = self.help_scroll.saturating_sub(10),
            KeyCode::PageUp => self.help_scroll = self.help_scroll.saturating_sub(10),
            KeyCode::Char('H') | KeyCode::Home => self.help_scroll = 0,
            KeyCode::Char('G') | KeyCode::End => self.help_scroll = usize::MAX / 2,
            _ => {}
        }
    }

    fn handle_mark_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let mark = match self.mark.as_mut() {
            Some(m) => m,
            None => {
                self.focus = Focus::Main;
                return;
            }
        };
        let len = mark.entries.len();
        let mv = |m: &mut MarkPane, f: &dyn Fn(usize) -> usize| {
            if len > 0 {
                m.selected = f(m.selected).min(len - 1);
            }
        };
        match key.code {
            KeyCode::Char('j') | KeyCode::Down if !ctrl => mv(mark, &|c| c + 1),
            KeyCode::Char('k') | KeyCode::Up if !ctrl => mv(mark, &|c| c.saturating_sub(1)),
            KeyCode::Char('d') if ctrl => mv(mark, &|c| c + 10),
            KeyCode::PageDown => mv(mark, &|c| c + 10),
            KeyCode::Char('u') if ctrl => mv(mark, &|c| c.saturating_sub(10)),
            KeyCode::PageUp => mv(mark, &|c| c.saturating_sub(10)),
            KeyCode::Char('H') | KeyCode::Home => mv(mark, &|_| 0),
            KeyCode::Char('G') | KeyCode::End => mv(mark, &|_| usize::MAX),
            KeyCode::Char('x') | KeyCode::Char('d') | KeyCode::Char(' ') => {
                if let Some(e) = mark.entries.get(mark.selected) {
                    let id = e.id;
                    self.toggle_mark(id);
                }
            }
            KeyCode::Char('a') => {
                self.mark = None;
                self.focus = Focus::Main;
            }
            KeyCode::Char('r') if ctrl => self.delete_marked(false),
            KeyCode::Char('t') if ctrl => self.delete_marked(true),
            _ => {}
        }
    }

    fn delete_marked(&mut self, trash: bool) {
        let mark = match self.mark.take() {
            Some(m) => m,
            None => return,
        };
        let mut remaining = Vec::new();
        for entry in mark.entries {
            let path = self.tree.path_of(entry.id);
            let res = if trash {
                super::trash::trash(&path)
            } else {
                delete_path(&path)
            };
            match res {
                Ok(()) => {
                    self.tree.remove(entry.id);
                }
                Err(_) => remaining.push(entry),
            }
        }
        if !remaining.is_empty() {
            let selected = remaining.len() - 1;
            self.mark = Some(MarkPane {
                entries: remaining,
                selected,
                offset: 0,
            });
        } else {
            self.focus = Focus::Main;
        }
        // make sure the view is still valid
        while !self.tree.is_alive(self.view_root) {
            match self.tree.parent(self.view_root) {
                Some(p) => self.view_root = p,
                None => break,
            }
        }
        if !self.in_glob_view && self.view_root != ROOT && !self.tree.has_children(self.view_root) {
            // stay in the (now empty) directory
        }
        let entries = self.entries();
        if self.selected_index(&entries).is_none() {
            self.selected = entries.first().copied();
        }
    }

    fn refresh_node(&mut self, id: NodeId) -> Option<NodeId> {
        let path = self.tree.path_of(id);
        let inodes = InodeFilter::default();
        let progress = Progress::default();
        let walker = Walker {
            opts: &self.walk_options,
            inodes: &inodes,
            progress: &progress,
        };
        let start = Instant::now();
        let pool = self.walk_options.thread_pool();
        let result = pool.install(|| walker.walk_root(&path));
        self.entries_processed = progress.entries.load(std::sync::atomic::Ordering::Relaxed);
        self.elapsed = start.elapsed();
        match result {
            Some(mut tmp) => {
                tmp.name = self.tree.nodes[id].name.clone();
                let new_id = self.tree.replace(id, tmp);
                self.missing.remove(&id);
                Some(new_id)
            }
            None => {
                self.tree.remove(id);
                None
            }
        }
    }

    fn remap_node(&mut self, old: NodeId, new: Option<NodeId>) {
        if self.selected == Some(old) {
            self.selected = new;
        }
        if let Some(m) = self.mark.as_mut() {
            for e in m.entries.iter_mut() {
                if e.id == old {
                    if let Some(n) = new {
                        e.id = n;
                    }
                }
            }
        }
        if let Some(g) = self.glob_view.as_mut() {
            for r in g.results.iter_mut() {
                if *r == old {
                    if let Some(n) = new {
                        *r = n;
                    }
                }
            }
        }
    }

    fn refresh_selected(&mut self) {
        let sel = match self.selected {
            Some(s) => s,
            None => return,
        };
        let new = self.refresh_node(sel);
        self.remap_node(sel, new);
        let entries = self.entries();
        if self.selected_index(&entries).is_none() {
            self.selected = entries.first().copied();
        }
    }

    fn refresh_all(&mut self) {
        let entries = self.entries();
        let mut total = 0;
        let start = Instant::now();
        for e in entries {
            let new = self.refresh_node(e);
            total += self.entries_processed;
            self.remap_node(e, new);
        }
        self.entries_processed = total;
        self.elapsed = start.elapsed();
        self.missing.clear();
        let entries = self.entries();
        if self.selected_index(&entries).is_none() {
            self.selected = entries.first().copied();
        }
    }
}

fn delete_path(path: &std::path::Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(path)?;
    if meta.is_dir() {
        std::fs::remove_dir_all(path)
    } else {
        std::fs::remove_file(path)
    }
}
