//! Moving files into the freedesktop.org trash.

use std::io::Write;
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};

fn home_trash() -> Option<PathBuf> {
    if let Some(d) = std::env::var_os("XDG_DATA_HOME") {
        if !d.is_empty() {
            return Some(PathBuf::from(d).join("Trash"));
        }
    }
    std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".local/share/Trash"))
}

fn encode(path: &Path) -> String {
    let mut out = String::new();
    for &b in path.as_os_str().as_bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~' | b'/') {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{:02X}", b));
        }
    }
    out
}

fn local_timestamp() -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let t = crate::interactive::time::local(now);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}",
        t.year, t.month, t.day, t.hour, t.minute, t.second
    )
}

fn absolute(path: &Path) -> std::io::Result<PathBuf> {
    let name = path.file_name().map(|n| n.to_os_string());
    let parent = path.parent().filter(|p| !p.as_os_str().is_empty());
    let parent = match parent {
        Some(p) => std::fs::canonicalize(p)?,
        None => std::env::current_dir()?,
    };
    Ok(match name {
        Some(n) => parent.join(n),
        None => std::fs::canonicalize(path)?,
    })
}

pub fn trash(path: &Path) -> std::io::Result<()> {
    let abs = absolute(path)?;
    std::fs::symlink_metadata(&abs)?;
    let trash = home_trash().ok_or_else(|| std::io::Error::other("no home directory"))?;
    let files = trash.join("files");
    let info = trash.join("info");
    std::fs::create_dir_all(&files)?;
    std::fs::create_dir_all(&info)?;
    let base = abs
        .file_name()
        .map(|n| n.to_os_string())
        .unwrap_or_default();
    let mut counter = 1;
    loop {
        let mut name = base.clone();
        if counter > 1 {
            name.push(format!(".{}", counter));
        }
        let mut info_name = name.clone();
        info_name.push(".trashinfo");
        let info_path = info.join(&info_name);
        let target = files.join(&name);
        if target.symlink_metadata().is_ok() {
            counter += 1;
            continue;
        }
        let file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&info_path);
        let mut file = match file {
            Ok(f) => f,
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                counter += 1;
                continue;
            }
            Err(e) => return Err(e),
        };
        write!(
            file,
            "[Trash Info]\nPath={}\nDeletionDate={}\n",
            encode(&abs),
            local_timestamp()
        )?;
        drop(file);
        match std::fs::rename(&abs, &target) {
            Ok(()) => return Ok(()),
            Err(e) => {
                let _ = std::fs::remove_file(&info_path);
                return Err(e);
            }
        }
    }
}
