//! Rendering of the interactive mode.

use super::app::{App, BarMode, Focus, Message, HELP_LINE_COUNT};
use super::tree::NodeId;
use ratatui::buffer::Buffer;
use ratatui::layout::Rect;
use ratatui::style::{Color, Modifier, Style};
use unicode_width::UnicodeWidthChar;
use unicode_width::UnicodeWidthStr;

const NAV_HINT: &str = " . = o|.. = u ── ⇊ = Ctrl+d|↓ = j|⇈ = Ctrl+u|↑ = k ";
const MAIN_BOTTOM_HINT: &str = " mark-move = d | mark-toggle = space | toggle-all = a ";
const MARK_BOTTOM_HINT: &str = " mark-toggle = space,d | remove-all = a";
const GLOB_HINT: &str = " search = enter | case = ^f | cancel = esc ";

const MARKED_FILE_COLOR: Color = Color::Rgb(176, 126, 0);

fn width(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

/// Write a string, clipped to `max_x` (exclusive). Returns the x position after the string.
fn put(buf: &mut Buffer, x: u16, y: u16, s: &str, max_x: u16, style: Style) -> u16 {
    let area = *buf.area();
    if y < area.y || y >= area.bottom() {
        return x;
    }
    let max_x = max_x.min(area.right());
    let mut x = x;
    for ch in s.chars() {
        if ch.is_control() {
            continue;
        }
        let w = UnicodeWidthChar::width(ch).unwrap_or(0) as u16;
        if w == 0 {
            continue;
        }
        if x + w > max_x {
            break;
        }
        let mut tmp = [0u8; 4];
        buf[(x, y)].set_symbol(ch.encode_utf8(&mut tmp)).set_style(style);
        let mut nx = x + 1;
        while nx < x + w {
            buf[(nx, y)].reset();
            nx += 1;
        }
        x += w;
    }
    x
}

fn fill(buf: &mut Buffer, x: u16, y: u16, n: u16, max_x: u16, style: Style) -> u16 {
    let mut x = x;
    let end = (x + n).min(max_x).min(buf.area().right());
    while x < end {
        buf[(x, y)].set_symbol(" ").set_style(style);
        x += 1;
    }
    x
}

fn draw_box(buf: &mut Buffer, area: Rect, style: Style) {
    if area.width < 1 || area.height < 1 {
        return;
    }
    let right = area.right() - 1;
    let bottom = area.bottom() - 1;
    for x in area.x..area.right() {
        let (top, bot) = if x == area.x {
            ("┌", "└")
        } else if x == right {
            ("┐", "┘")
        } else {
            ("─", "─")
        };
        buf[(x, area.y)].set_symbol(top).set_style(style);
        if area.height > 1 {
            buf[(x, bottom)].set_symbol(bot).set_style(style);
        }
    }
    for y in area.y + 1..bottom {
        buf[(area.x, y)].set_symbol("│").set_style(style);
        if area.width > 1 {
            buf[(right, y)].set_symbol("│").set_style(style);
        }
    }
}

/// Draw a block with a title and optionally hints. Returns the inner area.
fn draw_block(
    buf: &mut Buffer,
    area: Rect,
    title: &str,
    style: Style,
    top_hint: Option<&str>,
    bottom_hint: Option<&str>,
) -> Rect {
    draw_box(buf, area, style);
    if area.width > 2 {
        put(buf, area.x + 1, area.y, title, area.right() - 1, style);
    }
    let w = area.width as usize;
    if let Some(hint) = top_hint {
        let hw = width(hint);
        if width(title) + hw + 1 <= w {
            let x = area.x + (w - 1 - hw) as u16;
            put(buf, x, area.y, hint, area.right() - 1, style);
        }
    }
    if let Some(hint) = bottom_hint {
        let hw = width(hint);
        if hw < w && area.height > 1 {
            let x = area.x + (w - 1 - hw) as u16;
            put(buf, x, area.bottom() - 1, hint, area.right() - 1, style);
        }
    }
    Rect {
        x: area.x + 1.min(area.width),
        y: area.y + 1.min(area.height),
        width: area.width.saturating_sub(2),
        height: area.height.saturating_sub(2),
    }
}

fn border_style(focused: bool) -> Style {
    if focused {
        Style::default().add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::DarkGray)
    }
}

/// ratatui-like scrollbar on the given column.
fn draw_scrollbar(
    buf: &mut Buffer,
    x: u16,
    y: u16,
    height: u16,
    content_length: usize,
    position: usize,
    style: Style,
) {
    if content_length == 0 || height == 0 {
        return;
    }
    let track_length = height as f64;
    let viewport_length = height as f64;
    let max_position = content_length.saturating_sub(1) as f64;
    let start_position = (position as f64).clamp(0.0, max_position);
    let max_viewport_position = max_position + viewport_length;
    let end_position = start_position + viewport_length;
    let thumb_start = start_position * track_length / max_viewport_position;
    let thumb_end = end_position * track_length / max_viewport_position;
    let thumb_start = thumb_start.round().clamp(0.0, track_length - 1.0) as usize;
    let thumb_end = thumb_end.round().clamp(0.0, track_length) as usize;
    let thumb_length = thumb_end.saturating_sub(thumb_start).max(1);
    for i in 0..height as usize {
        let sym = if i >= thumb_start && i < thumb_start + thumb_length {
            "█"
        } else {
            "║"
        };
        buf[(x, y + i as u16)].set_symbol(sym).set_style(style);
    }
}

pub fn format_count(n: u64) -> String {
    if n < 1000 {
        n.to_string()
    } else if n < 1_000_000 {
        format!("{:.0}K", n as f64 / 1000.0)
    } else if n < 1_000_000_000 {
        format!("{:.0}M", n as f64 / 1_000_000.0)
    } else {
        format!("{:.0}G", n as f64 / 1_000_000_000.0)
    }
}

const PARTIAL_BLOCKS: [&str; 8] = ["", "▏", "▎", "▍", "▌", "▋", "▊", "▉"];

fn bar(fraction: f32, w: usize) -> String {
    let v = (fraction * w as f32).max(0.0);
    let mut full = v.floor() as usize;
    let mut partial = ((v - v.floor()) * 8.0).round() as usize;
    if partial >= 8 {
        full += 1;
        partial = 0;
    }
    let full = full.min(w);
    let mut s = "█".repeat(full);
    let mut used = full;
    if partial > 0 && used < w {
        s.push_str(PARTIAL_BLOCKS[partial]);
        used += 1;
    }
    s.push_str(&" ".repeat(w - used));
    s
}

/// Shorten a string in the middle so that it fits into `avail` columns.
fn middle_ellipsis(s: &str, avail: usize) -> String {
    if width(s) <= avail {
        return s.to_string();
    }
    if avail == 0 {
        return String::new();
    }
    let keep = (avail - 1) / 2;
    let chars: Vec<char> = s.chars().collect();
    let mut front = String::new();
    let mut fw = 0;
    for c in chars.iter() {
        let cw = UnicodeWidthChar::width(*c).unwrap_or(0);
        if fw + cw > keep {
            break;
        }
        fw += cw;
        front.push(*c);
    }
    let mut back: Vec<char> = Vec::new();
    let mut bw = 0;
    for c in chars.iter().rev() {
        let cw = UnicodeWidthChar::width(*c).unwrap_or(0);
        if bw + cw > keep {
            break;
        }
        bw += cw;
        back.push(*c);
    }
    back.reverse();
    let mut out = front;
    out.push('…');
    out.extend(back);
    out
}

/// Shorten a string from the left so it fits into `avail` columns.
fn left_ellipsis(s: &str, avail: usize) -> String {
    if width(s) <= avail {
        return s.to_string();
    }
    if avail == 0 {
        return String::new();
    }
    let chars: Vec<char> = s.chars().collect();
    let mut back: Vec<char> = Vec::new();
    let mut bw = 0;
    for c in chars.iter().rev() {
        let cw = UnicodeWidthChar::width(*c).unwrap_or(0);
        if bw + cw > avail - 1 {
            break;
        }
        bw += cw;
        back.push(*c);
    }
    back.reverse();
    let mut out = String::from("…");
    out.extend(back);
    out
}

pub struct Layout {
    pub header: Rect,
    pub entries: Rect,
    pub glob: Option<Rect>,
    pub help: Option<Rect>,
    pub mark: Option<Rect>,
    pub footer: Rect,
}

pub fn layout(app: &App, area: Rect) -> Layout {
    let header = Rect { height: 1.min(area.height), ..area };
    let footer = Rect {
        y: area.bottom().saturating_sub(1),
        height: 1.min(area.height),
        ..area
    };
    let main = Rect {
        y: area.y + 1,
        height: area.height.saturating_sub(2),
        ..area
    };
    let right_open = app.help_open || app.mark.is_some();
    let (left, right) = if right_open {
        let lw = main.width.div_ceil(2);
        (
            Rect { width: lw, ..main },
            Some(Rect {
                x: main.x + lw,
                width: main.width - lw,
                ..main
            }),
        )
    } else {
        (main, None)
    };
    let (entries, glob) = if app.glob_pane_open() {
        let gh = 3.min(left.height);
        (
            Rect {
                height: left.height - gh,
                ..left
            },
            Some(Rect {
                y: left.y + left.height - gh,
                height: gh,
                ..left
            }),
        )
    } else {
        (left, None)
    };
    let (help, mark) = match right {
        Some(r) => {
            if app.help_open && app.mark.is_some() {
                let th = r.height.div_ceil(2);
                (
                    Some(Rect { height: th, ..r }),
                    Some(Rect {
                        y: r.y + th,
                        height: r.height - th,
                        ..r
                    }),
                )
            } else if app.help_open {
                (Some(r), None)
            } else {
                (None, Some(r))
            }
        }
        None => (None, None),
    };
    Layout {
        header,
        entries,
        glob,
        help,
        mark,
        footer,
    }
}

pub fn draw(app: &mut App, buf: &mut Buffer) -> Option<(u16, u16)> {
    let area = *buf.area();
    let l = layout(app, area);
    draw_header(app, buf, l.header);
    draw_entries(app, buf, l.entries);
    if let Some(r) = l.help {
        draw_help(app, buf, r);
    }
    if let Some(r) = l.mark {
        draw_mark(app, buf, r);
    }
    let mut cursor = None;
    if let Some(r) = l.glob {
        cursor = draw_glob(app, buf, r);
    }
    draw_footer(app, buf, l.footer);
    cursor
}

fn draw_header(app: &App, buf: &mut Buffer, area: Rect) {
    if area.height == 0 {
        return;
    }
    let bg = if app.focus == Focus::Mark {
        Color::LightRed
    } else if app.mark.is_some() {
        Color::Yellow
    } else {
        Color::White
    };
    buf.set_style(area, Style::default().bg(bg));
    let base = Style::default().fg(Color::Black).bg(bg);
    let bold = base.add_modifier(Modifier::BOLD);
    let ul = base.add_modifier(Modifier::UNDERLINED);
    let spans: [(&str, Style); 9] = [
        (" D", bold),
        ("isk ", base),
        ("U", bold),
        ("sage ", base),
        ("A", bold),
        (&"nalyzer v2.32.2    "[..], base),
        ("(press ", ul),
        ("?", ul.add_modifier(Modifier::BOLD)),
        (" for help)", ul),
    ];
    let mut x = area.x;
    for (s, st) in spans.iter() {
        x = put(buf, x, area.y, s, area.right(), *st);
    }
}

fn draw_footer(app: &App, buf: &mut Buffer, area: Rect) {
    if area.height == 0 {
        return;
    }
    if let Some(Message::QuitConfirm) = app.message {
        let st = Style::default()
            .fg(Color::Black)
            .bg(Color::Yellow)
            .add_modifier(Modifier::BOLD);
        buf.set_style(area, st);
        put(buf, area.x, area.y, "Press esc or q again to exit...", area.right(), st);
        return;
    }
    let rev = Style::default().add_modifier(Modifier::REVERSED);
    buf.set_style(area, rev);
    let total: u128 = app.tree.nodes[super::tree::ROOT].size;
    let processed = if app.scanning {
        let elapsed = app.scan_start.elapsed();
        let secs = elapsed.as_secs_f64();
        let rate = if secs > 0.0 {
            (app.entries_processed as f64 / secs) as u64
        } else {
            0
        };
        format!(
            "Processed {} entries in {}s ({}/s)",
            app.entries_processed,
            elapsed.as_secs(),
            rate
        )
    } else {
        format!(
            "Processed {} entries in {:.2}s",
            app.entries_processed,
            app.elapsed.as_secs_f64()
        )
    };
    let text = format!(
        "Sort mode: {}  Total disk usage: {}  {}",
        app.sort.describe(),
        app.format.format_raw(total),
        processed
    );
    let mut x = put(buf, area.x, area.y, &text, area.right(), rev);
    let msg = if app.scanning {
        Some("-> scanning <-".to_string())
    } else {
        match &app.message {
            Some(Message::Info(m)) => Some(m.clone()),
            _ => None,
        }
    };
    if let Some(m) = msg {
        x = put(buf, x, area.y, "  ", area.right(), rev);
        let st = Style::default()
            .fg(Color::Red)
            .add_modifier(Modifier::BOLD | Modifier::SLOW_BLINK | Modifier::REVERSED);
        put(buf, x, area.y, &m, area.right(), st);
    }
}

fn entry_count_total(app: &App, entries: &[NodeId]) -> u64 {
    entries
        .iter()
        .map(|e| app.tree.nodes[*e].entry_count.unwrap_or(1))
        .sum()
}

fn draw_entries(app: &mut App, buf: &mut Buffer, area: Rect) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let focused = app.focus == Focus::Main;
    let bstyle = border_style(focused);
    let entries = app.entries();
    let total_size: u128 = entries.iter().map(|e| app.tree.nodes[*e].size).sum();
    let total_count = entry_count_total(app, &entries);
    let title_path = if app.in_glob_view || app.view_root == super::tree::ROOT {
        app.root_title.clone()
    } else {
        app.tree.path_of(app.view_root).display().to_string()
    };
    let title = format!(
        " {} ({} visible, {} total, {}) ",
        title_path,
        entries.len(),
        format_count(total_count),
        app.format.format_raw(total_size)
    );
    let inner = draw_block(
        buf,
        area,
        &title,
        bstyle,
        if focused { Some(NAV_HINT) } else { None },
        if focused { Some(MAIN_BOTTOM_HINT) } else { None },
    );
    let sel_idx = app.selected_index(&entries);
    let h = inner.height as usize;
    if h == 0 {
        return;
    }
    let offset = match sel_idx {
        Some(pos) => {
            if app.list_offset + h <= pos {
                pos + 1 - h
            } else if app.list_offset > pos {
                pos
            } else {
                app.list_offset
            }
        }
        None => 0,
    };
    app.list_offset = offset;
    let show_mtime = app.mtime_column_visible();
    let show_count = app.count_column_visible();
    for row in 0..h {
        let idx = offset + row;
        if idx >= entries.len() {
            break;
        }
        let id = entries[idx];
        let y = inner.y + row as u16;
        draw_entry_row(
            app,
            buf,
            inner,
            y,
            id,
            Some(idx) == sel_idx,
            focused,
            total_size,
            show_mtime,
            show_count,
        );
    }
    draw_scrollbar(
        buf,
        area.right() - 1,
        inner.y,
        inner.height,
        entries.len(),
        sel_idx.unwrap_or(0),
        bstyle,
    );
}

#[allow(clippy::too_many_arguments)]
fn draw_entry_row(
    app: &App,
    buf: &mut Buffer,
    inner: Rect,
    y: u16,
    id: NodeId,
    selected: bool,
    focused: bool,
    total_size: u128,
    show_mtime: bool,
    show_count: bool,
) {
    let node = &app.tree.nodes[id];
    let fraction: f32 = if total_size == 0 {
        0.0
    } else {
        node.size as f32 / total_size as f32
    };
    let base = if selected {
        let s = Style::default().add_modifier(Modifier::REVERSED);
        if focused {
            s.add_modifier(Modifier::BOLD)
        } else {
            s
        }
    } else {
        Style::default()
    };
    let sep_style = if selected && fraction > 0.9 {
        if focused {
            Style::default().add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        }
    } else {
        base
    };
    let max_x = inner.right();
    let mut x = inner.x;
    if show_mtime {
        let s = format!(" {}", super::time::format_mtime(node.mtime));
        x = put(buf, x, y, &s, max_x, base);
        x = put(buf, x, y, " | ", max_x, sep_style);
    }
    x = put(
        buf,
        x,
        y,
        &app.format.display(node.size),
        max_x,
        base.fg(Color::Green),
    );
    x = put(buf, x, y, " | ", max_x, sep_style);
    let pct = format!("{:>5.1}%", fraction * 100.0);
    let column = match app.bar_mode {
        BarMode::PercentageAndBar => format!(" {}  {}", pct, bar(fraction, 10)),
        BarMode::Percentage => format!(" {} ", pct),
        BarMode::Bar => bar(fraction, 10),
        BarMode::LongBar => bar(fraction, 19),
    };
    x = put(buf, x, y, &column, max_x, sep_style);
    x = put(buf, x, y, " | ", max_x, sep_style);
    if show_count {
        let c = match node.entry_count {
            Some(c) => format_count(c),
            None => String::new(),
        };
        x = put(buf, x, y, &format!("{:>4}", c), max_x, base);
        x = put(buf, x, y, " | ", max_x, sep_style);
    }
    let is_dir = node.is_dir && !app.in_glob_view;
    let name = app.display_name(id).display().to_string();
    let text = if is_dir {
        if name.starts_with('/') {
            name
        } else {
            format!("/{}", name)
        }
    } else {
        format!(" {}", name)
    };
    let fg = if app.missing.contains(&id) {
        Some(Color::Red)
    } else if app.is_marked(id) {
        Some(if node.is_dir { Color::Yellow } else { MARKED_FILE_COLOR })
    } else if is_dir {
        Some(Color::Cyan)
    } else {
        None
    };
    let name_style = match fg {
        Some(c) => base.fg(c),
        None => base,
    };
    if x < max_x {
        let avail = (max_x - x) as usize;
        let shown = middle_ellipsis(&text, avail);
        let nx = put(buf, x, y, &shown, max_x, name_style);
        fill(buf, nx, y, max_x - nx, max_x, name_style);
    }
}

pub fn help_lines() -> Vec<Vec<(String, Style)>> {
    let green = Style::default().fg(Color::Green);
    let title = Style::default().add_modifier(Modifier::BOLD | Modifier::UNDERLINED);
    let sections: Vec<(&str, Vec<(&str, Vec<&str>)>)> = vec![
        (
            "Pane control",
            vec![
                ("q/<Esc>", vec!["Close the current pane.", "Closes the program if no pane is open."]),
                ("<Tab>", vec!["Cycle between all open panes.", "Activate 'Marked Items' pane to delete selected files."]),
                ("?", vec!["Show or hide this help pane."]),
            ],
        ),
        (
            "Navigation",
            vec![
                ("j/<Down>", vec!["Move down 1 entry."]),
                ("k/<Up>", vec!["Move up 1 entry."]),
                ("o/l/<Enter>", vec!["Descent into the selected directory."]),
                ("<Right>", vec!["^"]),
                ("u/h/<Left>", vec!["Ascent one level into the parent directory."]),
                ("<Backspace>", vec!["^"]),
                ("Ctrl + d", vec!["Move down 10 entries."]),
                ("<Page Down>", vec!["^"]),
                ("Ctrl + u", vec!["Move up 10 entries."]),
                ("<Page Up>", vec!["^"]),
                ("H/<Home>", vec!["Move to the top of the list."]),
                ("G/<End>", vec!["Move to the bottom of the list."]),
            ],
        ),
        (
            "Display",
            vec![
                ("s", vec!["Toggle sort by size descending/ascending."]),
                ("m", vec!["Toggle sort by modified time descending/ascending."]),
                ("M", vec!["Show/hide modified time."]),
                ("c", vec!["Toggle sort by entries descending/ascending."]),
                ("C", vec!["Show/hide entry count."]),
                ("n", vec!["Toggle sort by name ascending/descending."]),
                ("g/S", vec!["Cycle through percentage display and bar options."]),
            ],
        ),
        (
            "Open/Mark/Search",
            vec![
                ("Shift + o", vec!["Open the selected entry with the associated program."]),
                ("d", vec!["Toggle the currently selected entry and move down."]),
                ("x", vec!["Mark the currently selected entry for deletion and move down."]),
                ("<Space>", vec!["Toggle the currently selected entry."]),
                ("a", vec!["Toggle all entries."]),
                ("/", vec!["Git-style glob search. Toggle case with 'I'.", "Search starts from the current directory."]),
                ("r", vec!["Refresh only the selected entry."]),
                ("R", vec!["Refresh all entries in the current view."]),
            ],
        ),
        (
            "Mark entries pane",
            vec![
                ("x/d/<Space>", vec!["Remove the selected entry from the list."]),
                ("a", vec!["Remove all entries from the list."]),
                ("Ctrl + r", vec!["Permanently delete all marked entries without prompt.", "This operation cannot be undone!"]),
                ("Ctrl + t", vec!["Move all marked entries to the trash bin.", "The entries can be restored from the trash bin."]),
            ],
        ),
        (
            "Application control",
            vec![("Ctrl + c", vec!["Close the application. No questions asked!"])],
        ),
    ];
    let mut lines: Vec<Vec<(String, Style)>> = Vec::new();
    for (name, items) in sections {
        lines.push(vec![(name.to_string(), title)]);
        lines.push(vec![]);
        for (key, descs) in items {
            for (i, d) in descs.iter().enumerate() {
                if i == 0 {
                    lines.push(vec![
                        (format!("{:>11}", key), green),
                        (format!(" => {}", d), Style::default()),
                    ]);
                } else {
                    lines.push(vec![(format!("{}{}", " ".repeat(15), d), Style::default())]);
                }
            }
        }
        lines.push(vec![]);
        lines.push(vec![]);
    }
    debug_assert_eq!(lines.len(), HELP_LINE_COUNT);
    lines
}

fn draw_help(app: &mut App, buf: &mut Buffer, area: Rect) {
    let focused = app.focus == Focus::Help;
    let bstyle = border_style(focused);
    let inner = draw_block(
        buf,
        area,
        "Help",
        bstyle,
        if focused { Some(NAV_HINT) } else { None },
        None,
    );
    if inner.width < 2 || inner.height < 2 {
        return;
    }
    let text_area = Rect {
        x: inner.x + 1,
        y: inner.y + 1,
        width: inner.width - 2,
        height: inner.height - 2,
    };
    let lines = help_lines();
    let visible = text_area.height as usize;
    let max_scroll = lines.len().saturating_sub(visible);
    if app.help_scroll > max_scroll {
        app.help_scroll = max_scroll;
    }
    for row in 0..visible {
        let idx = app.help_scroll + row;
        if idx >= lines.len() {
            break;
        }
        let y = text_area.y + row as u16;
        let mut x = text_area.x;
        for (s, st) in lines[idx].iter() {
            x = put(buf, x, y, s, text_area.right(), *st);
        }
    }
}

fn draw_mark(app: &mut App, buf: &mut Buffer, area: Rect) {
    let focused = app.focus == Focus::Mark;
    let bstyle = border_style(focused);
    let format = app.format;
    let mark = match app.mark.as_mut() {
        Some(m) => m,
        None => return,
    };
    let title = format!(
        "Marked {} items ({}) ",
        mark.total_count(),
        format.format_raw(mark.total_size())
    );
    let inner = draw_block(
        buf,
        area,
        &title,
        bstyle,
        if focused { Some(NAV_HINT) } else { None },
        if focused { Some(MARK_BOTTOM_HINT) } else { None },
    );
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let n = mark.entries.len();
    let show_prompt = focused && 2 * n + 2 <= inner.height as usize;
    let mut list = inner;
    if show_prompt {
        let y = inner.y;
        let white_on_black = Style::default()
            .fg(Color::White)
            .bg(Color::Black)
            .add_modifier(Modifier::BOLD);
        let black_on_yellow = Style::default()
            .fg(Color::Black)
            .bg(Color::Yellow)
            .add_modifier(Modifier::BOLD);
        let red_on_black = Style::default()
            .fg(Color::LightRed)
            .bg(Color::Black)
            .add_modifier(Modifier::BOLD | Modifier::SLOW_BLINK);
        let mut x = inner.x;
        x = put(buf, x, y, " Ctrl + t ", inner.right(), white_on_black);
        x = put(buf, x, y, " to trash or ", inner.right(), black_on_yellow);
        x = put(buf, x, y, " Ctrl + r ", inner.right(), red_on_black);
        x = put(buf, x, y, " to delete without prompt", inner.right(), black_on_yellow);
        fill(buf, x, y, inner.right().saturating_sub(x), inner.right(), black_on_yellow);
        list = Rect {
            y: inner.y + 1,
            height: inner.height - 1,
            ..inner
        };
    }
    let h = list.height as usize;
    if h == 0 {
        return;
    }
    let sel = mark.selected.min(n.saturating_sub(1));
    let offset = if mark.offset + h <= sel {
        sel + 1 - h
    } else if mark.offset > sel {
        sel
    } else {
        mark.offset
    };
    mark.offset = offset;
    let size_w = format.width() + 1;
    let w = list.width as usize;
    let name_w = w.saturating_sub(size_w + 1);
    for row in 0..h {
        let idx = offset + row;
        if idx >= n {
            break;
        }
        let e = &mark.entries[idx];
        let y = list.y + row as u16;
        let base = if focused && idx == sel {
            Style::default().add_modifier(Modifier::REVERSED | Modifier::BOLD)
        } else {
            Style::default()
        };
        let name_style = base.fg(if e.is_dir { Color::Yellow } else { MARKED_FILE_COLOR });
        let text = format!(" {}", e.path.display());
        let shown = if width(&text) > name_w.saturating_sub(2) {
            left_ellipsis(&text, name_w.saturating_sub(2))
        } else {
            text
        };
        let mut x = list.x;
        let name_end = list.x + name_w as u16;
        let nx = put(buf, x, y, &shown, name_end, name_style);
        fill(buf, nx, y, name_end.saturating_sub(nx), name_end, name_style);
        x = name_end;
        let size = format!("{} ", format.display(e.size));
        put(buf, x, y, &size, list.right(), base.fg(Color::Green));
    }
    draw_scrollbar(
        buf,
        area.right() - 1,
        list.y,
        list.height,
        n,
        sel,
        bstyle,
    );
}

fn draw_glob(app: &App, buf: &mut Buffer, area: Rect) -> Option<(u16, u16)> {
    let focused = app.focus == Focus::Glob;
    let bstyle = border_style(focused);
    let title = if app.glob_case_insensitive {
        "Git-Glob (case-insensitive)"
    } else {
        "Git-Glob (case-sensitive)"
    };
    let inner = draw_block(
        buf,
        area,
        title,
        bstyle,
        if focused { Some(GLOB_HINT) } else { None },
        None,
    );
    if inner.height == 0 || inner.width == 0 {
        return None;
    }
    let input = app.glob_input.as_ref()?;
    let text: String = input.text.iter().collect();
    put(buf, inner.x + 1, inner.y, &text, inner.right(), Style::default());
    if focused {
        let before: String = input.text[..input.cursor].iter().collect();
        let cx = inner.x + 1 + width(&before) as u16;
        return Some((cx.min(inner.right()), inner.y));
    }
    None
}
