                        (format!(" => {}", d), Style::default()),
                    ]);
                } else {
                    lines.push(vec![(format!("{}{}", " ".repeat(15), d), Style::default())]);
                }
            }
        }
        lines.push(vec![]);
        lines.push(vec![]);
    }
    debug_assert_eq!(lines.len(), HELP_LINE_COUNT);
    lines
}

fn draw_help(app: &mut App, buf: &mut Buffer, area: Rect) {
    let focused = app.focus == Focus::Help;
    let bstyle = border_style(focused);
    let inner = draw_block(
        buf,
        area,
        "Help",
        bstyle,
        if focused { Some(NAV_HINT) } else { None },
        None,
    );
    if inner.width < 2 || inner.height < 2 {
        return;
    }
    let text_area = Rect {
        x: inner.x + 1,
        y: inner.y + 1,
        width: inner.width - 2,
        height: inner.height - 2,
    };
    let lines = help_lines();
    let visible = text_area.height as usize;
    let max_scroll = lines.len().saturating_sub(visible);
    if app.help_scroll > max_scroll {
        app.help_scroll = max_scroll;
    }
    for row in 0..visible {
        let idx = app.help_scroll + row;
        if idx >= lines.len() {
            break;
        }
        let y = text_area.y + row as u16;
        let mut x = text_area.x;
        for (s, st) in lines[idx].iter() {
            x = put(buf, x, y, s, text_area.right(), *st);
        }
    }
}

fn draw_mark(app: &mut App, buf: &mut Buffer, area: Rect) {
    let focused = app.focus == Focus::Mark;
    let bstyle = border_style(focused);
    let format = app.format;
    let mark = match app.mark.as_mut() {
        Some(m) => m,
        None => return,
    };
    let title = format!(
        "Marked {} items ({}) ",
        mark.total_count(),
        format.format_raw(mark.total_size())
    );
    let inner = draw_block(
        buf,
        area,
        &title,
        bstyle,
        if focused { Some(NAV_HINT) } else { None },
        if focused { Some(MARK_BOTTOM_HINT) } else { None },
    );
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let n = mark.entries.len();
    let show_prompt = focused && 2 * n + 2 <= inner.height as usize;
    let mut list = inner;
    if show_prompt {
        let y = inner.y;
        let white_on_black = Style::default()
            .fg(Color::White)
            .bg(Color::Black)
            .add_modifier(Modifier::BOLD);
        let black_on_yellow = Style::default()
            .fg(Color::Black)
            .bg(Color::Yellow)
            .add_modifier(Modifier::BOLD);
        let red_on_black = Style::default()
            .fg(Color::LightRed)
            .bg(Color::Black)
            .add_modifier(Modifier::BOLD | Modifier::SLOW_BLINK);
        let mut x = inner.x;
        x = put(buf, x, y, " Ctrl + t ", inner.right(), white_on_black);
        x = put(buf, x, y, " to trash or ", inner.right(), black_on_yellow);
        x = put(buf, x, y, " Ctrl + r ", inner.right(), red_on_black);
        x = put(buf, x, y, " to delete without prompt", inner.right(), black_on_yellow);
        fill(buf, x, y, inner.right().saturating_sub(x), inner.right(), black_on_yellow);
        list = Rect {
            y: inner.y + 1,
            height: inner.height - 1,
            ..inner
        };
    }
    let h = list.height as usize;
    if h == 0 {
        return;
    }
    let sel = mark.selected.min(n.saturating_sub(1));
    let offset = if mark.offset + h <= sel {
        sel + 1 - h
    } else if mark.offset > sel {
        sel
    } else {
        mark.offset
    };
    mark.offset = offset;
    let size_w = format.width() + 1;
    let w = list.width as usize;
    let name_w = w.saturating_sub(size_w + 1);
    for row in 0..h {
        let idx = offset + row;
        if idx >= n {
            break;
        }
        let e = &mark.entries[idx];
        let y = list.y + row as u16;
        let base = if focused && idx == sel {
            Style::default().add_modifier(Modifier::REVERSED | Modifier::BOLD)
        } else {
            Style::default()
        };
        let name_style = base.fg(if e.is_dir { Color::Yellow } else { MARKED_FILE_COLOR });
        let text = format!(" {}", e.path.display());
        let shown = if width(&text) > name_w.saturating_sub(2) {
            left_ellipsis(&text, name_w.saturating_sub(2))
        } else {
            text
        };
        let mut x = list.x;
        let name_end = list.x + name_w as u16;
        let nx = put(buf, x, y, &shown, name_end, name_style);
        fill(buf, nx, y, name_end.saturating_sub(nx), name_end, name_style);
        x = name_end;
        let size = format!("{} ", format.display(e.size));
        put(buf, x, y, &size, list.right(), base.fg(Color::Green));
    }
    draw_scrollbar(
        buf,
        area.right() - 1,
        list.y,
        list.height,
        n,
        sel,
        bstyle,
    );
}

fn draw_glob(app: &App, buf: &mut Buffer, area: Rect) -> Option<(u16, u16)> {
    let focused = app.focus == Focus::Glob;
    let bstyle = border_style(focused);
    let title = if app.glob_case_insensitive {
        "Git-Glob (case-insensitive)"
    } else {
        "Git-Glob (case-sensitive)"
    };
    let inner = draw_block(
        buf,
        area,
        title,
        bstyle,
        if focused { Some(GLOB_HINT) } else { None },
        None,
    );
    if inner.height == 0 || inner.width == 0 {
        return None;
    }
    let input = app.glob_input.as_ref()?;
    let text: String = input.text.iter().collect();
    put(buf, inner.x + 1, inner.y, &text, inner.right(), Style::default());
    if focused {
        let before: String = input.text[..input.cursor].iter().collect();
        let cx = inner.x + 1 + width(&before) as u16;
        return Some((cx.min(inner.right()), inner.y));
    }
    None
}
