//! The interactive terminal user interface.

pub mod app;
pub mod draw;
pub mod glob;
pub mod time;
pub mod trash;
pub mod tree;

use crate::options::ByteFormat;
use crate::walk::{InodeFilter, WalkOptions};
use app::App;
use crossterm::event::{self, Event};
use crossterm::{execute, terminal};
use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;
use std::io::IsTerminal;
use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::sync::mpsc;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tree::{Progress, TmpNode, Walker};

enum ScanEvent {
    Root(TmpNode),
    Done,
}

pub fn run(
    walk_options: WalkOptions,
    format: ByteFormat,
    input: Vec<PathBuf>,
    no_entry_check: bool,
) -> std::io::Result<i32> {
    if !std::io::stderr().is_terminal() {
        return Err(std::io::Error::other(
            "Interactive mode requires a connected terminal",
        ));
    }
    let paths = crate::walk::derive_input_paths(input, walk_options.cross_filesystems)?;
    let root_title = std::env::current_dir()
        .map(|p| p.display().to_string())
        .unwrap_or_else(|_| ".".into());

    let mut app = App::new(root_title, format, walk_options.clone(), no_entry_check);

    // traversal in the background
    let progress = Arc::new(Progress::default());
    let (tx, rx) = mpsc::channel::<ScanEvent>();
    {
        let progress = progress.clone();
        let opts = walk_options.clone();
        std::thread::spawn(move || {
            let pool = opts.thread_pool();
            let inodes = InodeFilter::default();
            let walker = Walker {
                opts: &opts,
                inodes: &inodes,
                progress: &progress,
            };
            for path in paths {
                if progress.cancelled.load(Ordering::Relaxed) {
                    break;
                }
                crate::logging::info(&format!("Walking {:?}", path));
                if let Some(node) = pool.install(|| walker.walk_root(&path)) {
                    if tx.send(ScanEvent::Root(node)).is_err() {
                        return;
                    }
                }
            }
            let _ = tx.send(ScanEvent::Done);
        });
    }

    terminal::enable_raw_mode()?;
    let mut stderr = std::io::stderr();
    execute!(stderr, terminal::EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(std::io::stderr());
    let mut term = Terminal::new(backend)?;
    term.hide_cursor()?;
    term.clear()?;

    let result = event_loop(&mut term, &mut app, &rx, &progress);
    progress.cancelled.store(true, Ordering::Relaxed);

    let _ = term.show_cursor();
    let _ = execute!(std::io::stderr(), terminal::LeaveAlternateScreen);
    let _ = terminal::disable_raw_mode();
    result.map(|_| 0)
}

fn render(
    term: &mut Terminal<CrosstermBackend<std::io::Stderr>>,
    app: &mut App,
) -> std::io::Result<()> {
    let mut cursor = None;
    term.draw(|f| {
        let area = f.area();
        let buf = f.buffer_mut();
        let _ = area;
        cursor = draw::draw(app, buf);
        if let Some((x, y)) = cursor {
            f.set_cursor_position((x, y));
        }
    })?;
    Ok(())
}

fn event_loop(
    term: &mut Terminal<CrosstermBackend<std::io::Stderr>>,
    app: &mut App,
    rx: &mpsc::Receiver<ScanEvent>,
    progress: &Progress,
) -> std::io::Result<()> {
    let mut last_draw = Instant::now() - Duration::from_secs(1);
    let mut dirty = true;
    loop {
        if app.scanning {
            loop {
                match rx.try_recv() {
                    Ok(ScanEvent::Root(node)) => {
                        app.attach_root_child(node);
                        dirty = true;
                    }
                    Ok(ScanEvent::Done) | Err(mpsc::TryRecvError::Disconnected) => {
                        app.entries_processed = progress.entries.load(Ordering::Relaxed);
                        app.scan_finished();
                        dirty = true;
                        break;
                    }
                    Err(mpsc::TryRecvError::Empty) => break,
                }
            }
            if app.scanning {
                app.entries_processed = progress.entries.load(Ordering::Relaxed);
                if last_draw.elapsed() >= Duration::from_millis(250) {
                    dirty = true;
                }
            }
        }
        if dirty {
            render(term, app)?;
            last_draw = Instant::now();
            dirty = false;
        }
        let timeout = if app.scanning {
            Duration::from_millis(20)
        } else {
            Duration::from_secs(3600)
        };
        if event::poll(timeout)? {
            match event::read()? {
                Event::Key(key) => {
                    app.handle_key(key);
                    dirty = true;
                }
                Event::Resize(_, _) => {
                    term.autoresize()?;
                    dirty = true;
                }
                _ => {}
            }
            if app.should_quit {
                return Ok(());
            }
        }
    }
}
