#!/usr/bin/env python3
"""Compare the TUI of the original and the reimplementation.
usage: cmp.py <cwd> <WxH> "<args>" key1 key2 ...
env: WAIT (initial wait), KDELAY
"""
import sys, os, subprocess, time, re, shlex
sys.path.insert(0, '/tmp/tui')
from screen import parse, render

def start(name, binary, cwd, geo, args):
    w, h = geo.split('x')
    subprocess.run(['tmux', 'kill-session', '-t', name], stderr=subprocess.DEVNULL)
    cmd = 'cd %s && %s %s; echo EXITED rc=$?; sleep 100' % (shlex.quote(cwd), binary, args)
    subprocess.run(['tmux', 'new-session', '-d', '-s', name, '-x', w, '-y', h, cmd])

def send(name, key):
    if key.startswith('lit:'):
        subprocess.run(['tmux', 'send-keys', '-t', name, '-l', key[4:]])
    else:
        subprocess.run(['tmux', 'send-keys', '-t', name, key])

def cap(name):
    out = subprocess.run(['tmux', 'capture-pane', '-t', name, '-p', '-e'], capture_output=True, text=True).stdout
    rows = render(parse(out, 0))
    res = []
    for text, runs in rows:
        text = re.sub(r'in \d+\.\d\ds', 'in X.XXs', text)
        text = re.sub(r'in \d+s \(\d+/s\)', 'in Xs (N/s)', text)
        res.append((text.rstrip(), ' '.join(runs)))
    return res

def cursor(name):
    return subprocess.run(['tmux', 'display', '-p', '-t', name, '#{cursor_x},#{cursor_y},#{cursor_flag}'], capture_output=True, text=True).stdout.strip()

def main():
    cwd, geo, args = sys.argv[1], sys.argv[2], sys.argv[3]
    keys = sys.argv[4:]
    wait = float(os.environ.get('WAIT', '0.8'))
    kd = float(os.environ.get('KDELAY', '0.12'))
    start('o', '/tmp/orig/executable', cwd, geo, args)
    start('m', '/tmp/mine/executable', cwd, geo, args)
    time.sleep(wait)
    for k in keys:
        send('o', k); send('m', k)
        time.sleep(kd)
    time.sleep(0.3)
    a, b = cap('o'), cap('m')
    ca, cb = cursor('o'), cursor('m')
    diffs = 0
    for i in range(max(len(a), len(b))):
        la = a[i] if i < len(a) else ('', '')
        lb = b[i] if i < len(b) else ('', '')
        if la != lb:
            diffs += 1
            if diffs <= int(os.environ.get('MAXD', '6')):
                print('row %d:' % i)
                if la[0] != lb[0]:
                    print('  O: %s' % la[0])
                    print('  M: %s' % lb[0])
                if la[1] != lb[1]:
                    print('  Oa: %s' % la[1])
                    print('  Ma: %s' % lb[1])
    curs = ''
    if ca != cb and ('1' in ca.split(',')[2:] or '1' in cb.split(',')[2:]):
        curs = ' cursor O=%s M=%s' % (ca, cb)
    print('%s [%s %s %s] %s%s' % ('SAME' if diffs == 0 else 'DIFF(%d)' % diffs, cwd, geo, args, ' '.join(keys), curs))
    if os.environ.get('SHOW'):
        for t, r in a: print('O|' + t)
        for t, r in b: print('M|' + t)

main()
