        }
        if child.is_dir {
            extra = child.own;
        }
        count += match child.entry_count {
            Some(c) => c,
            None => child.own_count,
        };
    }
    node.model = model;
    node.size = model + extra;
    node.entry_count = Some(count);
    node.children = children;
}

