    /// Returns true if the entry should be counted.
    pub fn add(&mut self, ino: u64, nlink: u64) -> bool {
        if nlink <= 1 {
            return true;
        }
        match self.remaining.get_mut(&ino) {
            Some(1) => {
                self.remaining.remove(&ino);
                false
            }
            Some(count) => {
                *count -= 1;
                false
            }
            None => {
                self.remaining.insert(ino, nlink - 1);
                true
            }
        }
    }
}

/// The parts of the metadata we care about.
#[derive(Clone, Debug)]
pub struct Meta {
    pub len: u64,
    pub blocks: u64,
    pub nlink: u64,
    pub ino: u64,
    pub dev: u64,
    pub mtime: SystemTime,
    pub is_dir: bool,
}

impl Meta {
    pub fn from(m: &Metadata) -> Meta {
        Meta {
            len: m.len(),
            blocks: m.blocks(),
            nlink: m.nlink(),
            ino: m.ino(),
            dev: m.dev(),
            mtime: m.modified().unwrap_or(UNIX_EPOCH),
            is_dir: m.is_dir(),
        }
    }
}

/// An entry as found on disk, before hard-link and device filtering.
#[derive(Debug)]
pub struct RawEntry {
    pub name: PathBuf,
    /// None if the metadata couldn't be obtained.
    pub meta: Option<Meta>,
    pub children: Vec<RawEntry>,
}

impl RawEntry {
    pub fn count(&self) -> u64 {
        1 + self.children.iter().map(|c| c.count()).sum::<u64>()
    }
}

/// Counters that can be observed while scanning.
pub struct ScanProgress {
    pub entries: AtomicU64,
    pub cancelled: AtomicBool,
}

impl Default for ScanProgress {
    fn default() -> Self {
        ScanProgress {
            entries: AtomicU64::new(0),
            cancelled: AtomicBool::new(false),
        }
    }
}

impl WalkOptions {
    /// The counted size of an entry: zero for repeated hard links and entries on other devices.
    pub fn counted(&self, inodes: &mut InodeFilter, m: &Meta, device: u64) -> (u128, bool) {
        if (self.count_hard_links || inodes.add(m.ino, m.nlink))
            && (self.cross_filesystems || m.dev == device)
        {
            let size = if self.apparent_size {
                m.len
            } else {
                m.blocks.saturating_mul(512)
            };
            (size as u128, true)
        } else {
            (0, false)
        }
    }

    /// Scan a root path. Returns None if the root itself can't be accessed, along with the
    /// device id used for the cross-filesystem checks.
    pub fn scan_root(&self, path: &Path, progress: &ScanProgress) -> Option<(RawEntry, u64)> {
        let followed = std::fs::metadata(path).ok()?;
        let meta = std::fs::symlink_metadata(path).ok()?;
        progress.entries.fetch_add(1, Ordering::Relaxed);
        let device = followed.dev();
        let mut root = RawEntry {
            name: path.to_path_buf(),
            meta: Some(Meta::from(&meta)),
            children: Vec::new(),
        };
        if followed.is_dir() {
            let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
            if !self.is_ignored(&canonical) {
                root.children = self.scan_children(path, &canonical, device, progress);
            }
        }
        Some((root, device))
    }

    fn scan_children(
        &self,
        dir: &Path,
        canonical: &Path,
        device: u64,
        progress: &ScanProgress,
    ) -> Vec<RawEntry> {
        if progress.cancelled.load(Ordering::Relaxed) {
            return Vec::new();
        }
        let rd = match std::fs::read_dir(dir) {
            Ok(rd) => rd,
            Err(_) => return Vec::new(),
        };
        let mut children: Vec<(RawEntry, Option<(PathBuf, PathBuf)>)> = Vec::new();
        for entry in rd {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };
            progress.entries.fetch_add(1, Ordering::Relaxed);
            let path = entry.path();
            let name = PathBuf::from(entry.file_name());
            match std::fs::symlink_metadata(&path) {
                Ok(m) => {
                    let mut descend = None;
                    if m.is_dir() && (self.cross_filesystems || m.dev() == device) {
                        let canon = canonical.join(entry.file_name());
                        if !self.is_ignored(&canon) {
                            descend = Some((path, canon));
                        }
                    }
                    children.push((
                        RawEntry {
                            name,
                            meta: Some(Meta::from(&m)),
                            children: Vec::new(),
                        },
                        descend,
                    ));
                }
                Err(_) => children.push((
                    RawEntry {
                        name,
                        meta: None,
                        children: Vec::new(),
                    },
                    None,
                )),
            }
        }
        children.par_iter_mut().for_each(|(child, descend)| {
            if let Some((path, canon)) = descend.take() {
                child.children = self.scan_children(&path, &canon, device, progress);
            }
        });
        children.into_iter().map(|(c, _)| c).collect()
    }
}

