//! The `aggregate` subcommand: print the disk usage of the given paths.

use crate::options::ByteFormat;
use crate::walk::{InodeFilter, RawEntry, ScanProgress, WalkOptions};
use std::io::Write;
use std::path::PathBuf;

#[derive(Debug)]
#[allow(dead_code)]
pub struct Statistics {
    pub entries_traversed: u64,
    pub smallest_file_in_bytes: u64,
    pub largest_file_in_bytes: u64,
}

struct Stats {
    entries: u64,
    smallest: u64,
    largest: u64,
}

impl Stats {
    fn record(&mut self, size: u128) {
        let size = size.min(u64::MAX as u128) as u64;
        self.entries += 1;
        self.smallest = self.smallest.min(size);
        self.largest = self.largest.max(size);
    }
}

/// Sum up the sizes of the entry and all its children in traversal order.
/// Returns (bytes, errors).
fn fold(
    opts: &WalkOptions,
    inodes: &mut InodeFilter,
    stats: &mut Stats,
    entry: &RawEntry,
    device: u64,
) -> (u128, u64) {
    let mut bytes = 0;
    let mut errors = 0;
    match &entry.meta {
        Some(m) => {
            let (size, _) = opts.counted(inodes, m, device);
            stats.record(size);
            bytes += size;
        }
        None => {
            stats.record(0);
            errors += 1;
        }
    }
    for child in entry.children.iter() {
        let (b, e) = fold(opts, inodes, stats, child, device);
        bytes += b;
        errors += e;
    }
    (bytes, errors)
}

fn write_line(
    out: &mut impl Write,
    format: ByteFormat,
    bytes: u128,
    path: &str,
    colored_path: bool,
    errors: u64,
) -> std::io::Result<()> {
    write!(out, "\x1b[32m{}\x1b[39m ", format.display(bytes))?;
    if colored_path {
        write!(out, "\x1b[36m{}\x1b[39m", path)?;
    } else {
        write!(out, "{}", path)?;
    }
    if errors > 0 {
        write!(
            out,
            "  <{} IO Error{}>",
            errors,
            if errors > 1 { "s" } else { "" }
        )?;
    }
    writeln!(out)
}

/// Run the aggregation, returning the total number of errors and the statistics.
pub fn aggregate(
    out: &mut impl Write,
    opts: &WalkOptions,
    compute_total: bool,
    sort_by_size: bool,
    format: ByteFormat,
    paths: Vec<PathBuf>,
) -> std::io::Result<(u64, Statistics)> {
    let pool = opts.thread_pool();
    let mut inodes = InodeFilter::default();
    let mut stats = Stats {
        entries: 0,
        smallest: u64::MAX,
        largest: 0,
    };
    let progress = ScanProgress::default();
    let mut total: u128 = 0;
    let mut total_errors: u64 = 0;
    let mut results: Vec<(PathBuf, u128, u64)> = Vec::new();
    let num_roots = paths.len();
    for path in paths {
        let scanned = pool.install(|| opts.scan_root(&path, &progress));
        let (bytes, errors, accessible) = match scanned {
            Some((root, device)) => {
                let (b, e) = fold(opts, &mut inodes, &mut stats, &root, device);
                (b, e, true)
            }
            None => (0, 1, false),
        };
        total += bytes;
        total_errors += errors;
        if sort_by_size {
            results.push((path, bytes, errors));
        } else if accessible {
            write_line(
                out,
                format,
                bytes,
                &path.display().to_string(),
                !path.is_file(),
                errors,
            )?;
        }
    }
    if sort_by_size {
        results.sort_by_key(|r| r.1);
        for (path, bytes, errors) in &results {
            write_line(
                out,
                format,
                *bytes,
                &path.display().to_string(),
                !path.is_file(),
                *errors,
            )?;
        }
    }
    if num_roots > 1 && compute_total {
        write_line(out, format, total, "total", false, total_errors)?;
    }
    Ok((
        total_errors,
        Statistics {
            entries_traversed: stats.entries,
            smallest_file_in_bytes: if stats.smallest == u64::MAX { 0 } else { stats.smallest },
            largest_file_in_bytes: stats.largest,
        },
    ))
}
EOF
echo ok"}

