        if sort_by_size {
            results.push((path, bytes, errors));
        } else if accessible {
            write_line(
                out,
                format,
                bytes,
                &path.display().to_string(),
                !path.is_file(),
                errors,
            )?;
        }
    }
    if sort_by_size {
        results.sort_by_key(|r| r.1);
        for (path, bytes, errors) in &results {
            write_line(
                out,
                format,
                *bytes,
                &path.display().to_string(),
                !path.is_file(),
                *errors,
            )?;
        }
    }
    if num_roots > 1 && compute_total {
        write_line(out, format, total, "total", false, total_errors)?;
    }
    Ok((
        total_errors,
        Statistics {
            entries_traversed: stats.entries,
            smallest_file_in_bytes: if stats.smallest == u64::MAX { 0 } else { stats.smallest },
            largest_file_in_bytes: stats.largest,
        },
    ))
}
